export default [{"id":380,"question":"النيابة في الرمي هل يوجد لها دليلٌ من الحديث الصحيح؟ لأن بعض العلماء يقولون: إن لفظ جابر (رمينا عن الصبية...) ليس بثابتٍ؟","title":"ما دليل جواز النيابة في الرمي؟","answer":"الجواب: الحديث في سنده ضعفٌ لا شكَّ، لكن عمدة العلماء بأن الصّبيان والمرضى وكبار السن لا يستطيعون الرمي، والقاعدة: الشرع جوّز الإنابة فيما يتعذر فيه المباشرة، فالإنسان يستنيب في إخراج الزكاة مَن يُؤديها عنه؛ لأنه حقٌّ مالي، ويستنيب في أمورٍ كثيرةٍ مَن يؤدي عنه، إذا كان ذلك واجبًا عليه، وهذا الرمي واجب، فاستناب فيه مَن يؤديه عنه، كما يستنيب في الحجّة برمتها والعمرة برمتها مَن يؤديها عنه إذا كان عاجزًا، أو كان ميتًا يستنيب عنه وليه أو وكيل وصيته، فهذا عاجزٌ فاستناب عنه.\nوحديث جابر شاهد ومرجح، وليس هو العمدة، ولكن العمدة أن أصل الحج تجوز فيه الإنابة للعاجز، وأصل العمرة كذلك، وهذا جزء منه؛ عجز عنه الصبي أو نحوه فاستناب فيه، ولا وجه لإلغائه؛ لأن الواجب إذا أمكن الاستنابة فيه لم يسقط، وإنما يسقط إذا لم يتيسر القيام به من غير صاحبه، فالأصل أن الواجب باقٍ، وعلى المكلَّف أن يتخلص منه بنفسه أو بنائبه، وهذا ممكنٌ في الرمي، وهكذا في حقِّ العاجز الذي يجوز له أن يستنيب في أصل الحج والعمرة، لو عجز عن الطواف أو عجز عن السعي استناب: كالشيخ الكبير، والعجوز الكبيرة، والذي لا يُرجى برؤه لو حضر إلى الحجِّ وعجز عن بعض الأشياء أدَّاها عنه غيرُه، كما يؤدي عنه أصل الحج وأصل العمرة.","link":"https://binbaz.org.sa/fatwas/4701/ما-دليل-جواز-النيابة-في-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0436.mp3","categories":["النيابة في الحج"]},{"id":387,"question":"هل يجوز عمل عمرة لوالدتي التي تجاوزت سن الخامسة والستين، وأنا الآن أقضي فريضة الحج هذا العام؟","title":"حكم أداء العمرة عن العاجز وكبير السن","answer":"الجواب: إذا كانت عاجزةً لا تستطيع المجيء للحج لكبر سنِّها وعجزها لمرضٍ أصابها أو كبر سنٍّ أعاقها؛ فلا بأس. أما إذا كانت تستطيع المجيء لصحة جسمها؛ فلا يجوز أن ينوب عنها، لا في حجٍّ، ولا في عمرةٍ؛ لأن الرخصة إنما جاءت فيمَن عجز لكبر سنِّه.","link":"https://binbaz.org.sa/fatwas/4719/حكم-اداء-العمرة-عن-العاجز-وكبير-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0443.mp3","categories":["النيابة في الحج"]},{"id":612,"question":"الحج عن الميت حتى وإن كان متساهلاً وما كان ينوي الحج؟","title":"حكم الحج عمن تساهل في الحج قبل موته","answer":"الجواب: ولو، إذا كان مسلمًا يحج عنه، أما إذا كان كافرًا فلا.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6451/حكم-الحج-عمن-تساهل-في-الحج-قبل-موته","audio":"https://files.zadapps.info/binbaz.org.sa/maram179 - 01 -  Start.mp3","categories":["النيابة في الحج"]},{"id":1105,"question":"ما حكم الرمي نيابةً عن المرأة، خشية الزحام والفتنة، مع أنَّ المرأة قادرة على الرمي؟ وماذا يلزم من فعل ذلك؟","title":"حكم الرمي عن المرأة خشية الزحام والفتنة","answer":"الجواب:\nإذا اشتدَّ الزحامُ ولم يتيسر الرمي في وقتٍ مناسبٍ؛ جاز التوكيل، ولا يُخاطَر بها، عنها وعن المريض، المرأة والمريض والشيخ الكبير والحامل والمرضع التي ليس لديها مَن يحفظ أولادها يرمي عنهم بالوكالة. وإذا كانت سليمةً وقويةً في الوقت المناسب: كالليل، ترمي بنفسها، فإنَّ الرمي يكون في يوم العيد، بعد النصف من ليلة العيد، ويوم العيد كله رمي، وليلة العيد في حقِّ مَن لم يرمِ يوم العيد، ليلة النشر، يرمي أيضًا ليلة إحدى عشر عن يوم العيد جمرة العقبة، واليوم الحادي عشر يرمي بعد الزوال، وهكذا بعد الغروب، إلى آخر الليل، وهكذا اليوم الثاني عشر يرمي بعد الزوال، وبعد الغروب، إلى آخر الليل، على الصحيح.\nوهكذا يوم الثالث عشر: يرمي بعد الزوال إلى غروب شمس اليوم الأخير، ينتهي بغروب الشمس، بعد الزوال إلى غروب الشمس، وينتهي الرمي بعد ذلك، فإذا كان لم يتيسر رميها في وقتٍ تستطيع فيه أن تُوكِّل مَن يرمي عنها؛ لأجل خطر الزحام، أو لأنها ضعيفة الجسم، أو هفرة لا تُحسن الرمي، أو كبيرة السن، أو حُبلى تخشى على نفسها، أو شبه ذلك ممن يشقّ عليها الرمي لأسبابٍ أوجبت ذلك.\nوالوكيل يقوم مقامها، يرمي عنها وعن نفسه في موقفٍ واحدٍ، يرمي عن المرأة، وعن الشيخ الكبير، وعن المريض، يرمي عن نفسه، وعن مُوكِّله بموقفٍ واحدٍ يوم العيد عند الجمرة، وهو واقفٌ، وهكذا الأيام الأخرى، يرمي الأولى عن نفسه وعن مُوكليه، والوسطى عن نفسه وعن مُوكليه، والأخيرة عن نفسه وعن مُوكليه، على واحدةٍ واحدة، يُكبِّر مع كل حصاةٍ، ويبدأ بنفسه.","link":"https://binbaz.org.sa/fatwas/21174/حكم-الرمي-عن-المراة-خشية-الزحام-والفتنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0970ما حكم الرمي نيابة عن المرأة خشية الزحام والفتنة مع أنها قادرة على الرمي وما يلزم من فعل ذلك؟.mp3","categories":["النيابة في الحج"]},{"id":1238,"question":"مَن اعتمر عن غيره وحجَّ عن نفسه مُفردًا أو العكس هل يُعتبر متمتعًا أم لا؟","title":"حكم من اعتمر عن غيره وحج عن نفسه","answer":"الجواب:\nنعم؛ لعموم الآية، لأنَّ الله قال: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196]، ولم يقل: عن شخصٍ أو شخصين، سواء تمتع أو حجَّ عن شخصٍ أو عن شخصين، هو متمتع، سواء كانت العمرةُ له والحجُّ لغيره، أو العمرةُ لغيره والحجُّ له، كله واحد، أو الحجُّ لواحدٍ والعمرة لواحدٍ، كله واحد، عليه الهدي.","link":"https://binbaz.org.sa/fatwas/21297/حكم-من-اعتمر-عن-غيره-وحج-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1040من اعتمر عن غيره وحج عن نفسه مفرداً أو العكس هل يعتبر متمتعاً أو لا؟ ابن باز.mp3","categories":["النيابة في الحج"]},{"id":1240,"question":"ما حكم الحجّ عن الأحياء؟","title":"هل يجوز الحجّ عن الأحياء؟","answer":"الجواب:\nإذا كان الحيُّ عاجزًا لا يستطيع فلا بأس، كما في حديث الخثعميَّة وأبي رزين، حيث قالت: إنَّ أباها شيخٌ كبيرٌ لا يستطيع الحجَّ ولا الظّعن، وقال أبو رزين: إنه شيخٌ كبيرٌ لا يثبت على الراحلة.  هذا يُحجّ عنه فرضًا ونفلًا، أما الذي يقوى؛ لا يُحجّ عنه، فهو يحجّ بنفسه، ولو نافلة، هذا هو الأرجح.","link":"https://binbaz.org.sa/fatwas/21295/هل-يجوز-الحج-عن-الاحياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1038ما حكم الحج عن الأحياء؟ ابن باز.mp3","categories":["النيابة في الحج"]},{"id":1275,"question":"اعتمرتُ مع والدي، والذي لم يستطع إكمال السَّعي بين الصَّفا والمروة بسبب ألمٍ شديدٍ أصاب ركبته، وقد أكملتُ عنه ثلاثة أشواطٍ، فهل يُجزئ ذلك؟ علمًا بأنَّه قد قال عند الميقات: فإن حبسني حابسٌ فمحلي حيث حبستني. أفيدوني جزاكم الله خيرًا.","title":"هل يجوز النيابة في إكمال السعي عمن عجز","answer":"الجواب:\nلا، ما يجوز ذلك، عليه أن يسعى ولو محمولًا، ما تنوب عنه أنت، يسعى ولو محمولًا، وإذا كان ما فعل؛ عليه أن يُعيد السَّعي الآن بنية العمرة السَّابقة، يُعيد السَّعي بنية العمرة السَّابقة، ويُعيد التَّقصير من رأسه أو الحلق، وإن كان أتى زوجته فعليه شاة العمرة، وعليه أن يُعيد العمرة أيضًا، إن كان أتى زوجته –جامعها- فالعمرة فسدت، وعليه أن يكملها بالسعي ولو محمولًا، وإن كان طاب الحمد لله، يمشي ويُعيد التَّقصير أو الحلق، ثم يُعيد العمرة برمَّتها من الميقات الذي أحرم به من العمرة الأولى منه؛ لأن العمرة إذا جامع فيها قبل حلّها فسدت قبل أن يكمل السعي، فيُكملها بالسَّعي، ويُعيد التَّقصير والحلق، وتمت والحمد لله، ولا  شيء عليه، إلا إذا كان جامع زوجته بعد هذا؛ فعليه أن يُعيد العمرة مرةً أخرى، مع شاةٍ تُذبح في مكة للفقراء عن وطئه لها قبل كمال العمرة.\nوأما أنت: فكونك كمّلت عنه لا؛ لأنه وجب عليه... ولو محمولًا، ولو في عربانة، يقول الله جلَّ وعلا: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]، هذا لو كان عاجزًا ما يستطيع أن يصل إلى مكة، ولا يستطيع أن يطوف، ولا أن يسعى؛ يُحجج عنه. أما الذي جاء ووصل وعرض له عارضٌ برِجْلِه أو في ركبته؛ فهذا يُحْمَل.","link":"https://binbaz.org.sa/fatwas/21330/هل-يجوز-النيابة-في-اكمال-السعي-عمن-عجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1073هل يجوز أن أنوب عن أبي في السعي إذا لم يستطع أكماله؟ ابن باز فتاوى.mp3","categories":["النيابة في الحج"]},{"id":1942,"question":"الأضحية على الأموات؟","title":"حكم الأضحية عن الأموات وتخصيصهم بها","answer":"الجواب:\nداخلة في العموم، تعمّها الأحاديث، إذا ضحَّى عنه وعن أهل بيته يعمّها.\nس: تخصيصهم بالأُضحية؟\nج: لا مانع؛ لأنها صدقة، الضحية صدقة.\nس: مَن قال أنها بدعة؟\nج: لا، ما عنده خبر؛ لأنها صدقة ومساعدة وتقرّب إلى الله جل وعلا بالذبح.\nس: تدخل في باب الصَّدقة؟\nج: نعم، والنبي ﷺ ضحَّى بالضحية عنه وعن أهل بيته، وأهل بيته فيهم الميت وفيهم الحي، فيهم خديجة ميتة، وفيهم بعض بناته عليه الصلاة والسلام.\nس: تخصيص الأموات؟\nج: إذا خصَّهم لا بأس، كان النبيُّ ﷺ كثيرًا ما يُضَحِّي بذبح الشاة عن خديجة، يتصدق بها عن خديجة، ويقسمها بين صواحبات خديجة بعد وفاتها رضي الله عنها.","link":"https://binbaz.org.sa/fatwas/22055/حكم-الاضحية-عن-الاموات-وتخصيصهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإضحية عن الأموات وتخصيصهم بها.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":2714,"question":"بالنسبة للذي حجّ عن الغير ما يُشترط أنه يُوصِي؟","title":"هل يجب أن يُوصِي مَن يحُجُّ عن الغير؟","answer":"الجواب: ولو ما وصّى، لكن يُشترط أنه قد حج عن نفسه، لا بدّ للحاج عن غيره أن يكون قد حج عن نفسه، قد اعتمر عن نفسه.\nس: إذا كان مُفَرِّطًا في تَرْك الحج؟\nالشيخ: ولو مفرِّط يُحَجُّ عنه ويُدْعَى له بالمغفرة والعفو.","link":"https://binbaz.org.sa/fatwas/22856/هل-يجب-ان-يوصي-من-يحج-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يوصي من حج عن الغير.mp3","categories":["النيابة في الحج"]},{"id":2794,"question":"هل يجوز أن توكل المرأة في رمي الجمرات خشية الزحام وحجها فريضة؟ أو ترمي بنفسها بالليل؟ ومتى يكون آخر ساعة في الليل؟","title":"هل للمرأة أن توكل في الرَّمي للفريضة؟","answer":"الجواب: الواجب ترمي بنفسها، الواجب على الإنسان يرمى، رمى أزواج النبي  ﷺ ورمى النساء مع النبي ﷺ في الأوقات المناسبة، الليل كله رمي، كل الليل رمي، ليلة العيد بعد النصف، وليلة إحدى عشر عن يوم العيد كله، كل الليل من أوله إلى آخره، وليلة الثاني عشر عن يوم الحادي عشر، وليلة الثالثة عشر عن يوم الثاني عشر، أما ليلة أربعة عشر فما هي محل رمي، ينتهي بغروب يوم الثالث عشر.\nس: بالنسبة للرمي ما في عذر إن كان المرأة كبيرة؟\nالشيخ: الرجل الكبير، والمرأة الكبيرة، والمريض معذور .\nس: هل ممكن ينيب ؟\nالشيخ: يوكّلوا من يرمي عنهم.","link":"https://binbaz.org.sa/fatwas/22942/هل-للمراة-ان-توكل-في-الرمي-للفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمرأة أن توكل في رمي الجمرات وحجها فريضة.mp3","categories":["النيابة في الحج"]},{"id":2807,"question":"هل يصح لي أن أحج عن زوجتي العاجزة؟","title":"هل يجوز الحج عن الزوجة العاجزة؟","answer":"الجواب: فرضها؟\nس: لا، قد حجت.\nالشيخ: عاجزة؟\nس: عاجزة، وهي في ذمتي، يصلح أخذ الحجة أوْ لا؟\nالشيخ: ما في بأس، نعم ما في حرج.","link":"https://binbaz.org.sa/fatwas/22956/هل-يجوز-الحج-عن-الزوجة-العاجزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحج عن الزوجة العاجزة.mp3","categories":["النيابة في الحج"]},{"id":3594,"question":"شخص يريد أن يحج تطوعًا لنفسه، وطلبت منه والدته أن يحج عن جدته المتوفاه، فهل الأفضل يحج عن نفسه، أو يطيع والدته ويحج عن جدته؟","title":"حكم من أمرته أمه بالحج عن جدته المتوفاة؟","answer":"الجواب: يطيع والدته ويحج لجدته، ويبشر بالخير، يُرجى له أجر الحجة.","link":"https://binbaz.org.sa/fatwas/23776/حكم-من-امرته-امه-بالحج-عن-جدته-المتوفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في النيابة في الحج.mp3","categories":["النيابة في الحج"]},{"id":4932,"question":"هل يجوز للصبي أن يحج عن البالغ، يعني رجل يأخد إبنه، ثم يجعل حجة ابنه عن أبيه؟","title":"هل يجوز للصبي أن يحج عن البالغ؟","answer":"الجواب: لا لا، الصبي يحج عن نفسه، لا يحج عن غيره حتى يؤدي الفريضة.\nس: إذا كان حج قبل ذلك؟\nالشيخ: حتى يؤدي الفريضة، ما بعد أدى الفريضة، الصبي ما له فريضة حتى يبلغ.","link":"https://binbaz.org.sa/fatwas/27023/هل-يجوز-للصبي-ان-يحج-عن-البالغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للصبي أن يحج عن البالغ.mp3","categories":["النيابة في الحج"]},{"id":5293,"question":"لي جد كبير في السن وأولاده لا يستطيعون أن يحجوا عنه، وهو مريض وكبير في السن، فهل يجوز لي وأنا ابن ابنته أن أحج عنه وعن جدتي علمًا بأن جدتي قد توفيت؟","title":"هل يجوز لابن البنت الحج عن جده المريض؟","answer":"الجواب: مشكور، لا بأس أن تحج عنه، جزاك الله خيرًا، هذا من الصلة ومن البر، إذا كان مريضًا مرضًا لا يُرجى برؤه أو كبيرًا في السن عاجزًا تحج عنه أو ميتًا كذلك، هذا من البر والصلة، فأنت مشكور ومأجور، جاءت امرأة قالت: يا رسول الله، إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه؟ قال: حجي عن أبيكِ وجاء رجل فقال: يا رسول الله، إن أبي شيخ كبير، لا يثبت على الراحلة أفأحج عنه وأعتمر؟ قال: حج عن أبيك واعتمر فإذا حججت عن جدك أو جدتك أو غيرهما من الأموات أو كبار السن العاجزين؛ فلا بأس، والعمرة كذلك.[1]","link":"https://binbaz.org.sa/fatwas/30941/هل-يجوز-لابن-البنت-الحج-عن-جده-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 013.mp3","categories":["النيابة في الحج"]},{"id":5441,"question":"أبي كبير في السن، والحج فيه مشقة مادية عليه، فهل يجوز أن أحج عنه حيث إني أعمل بالمملكة؟","title":"ما حكم الحج عن كبير السن العاجز؟","answer":"الجواب: إذا كان كبير السن يعجز عن القيام بأمور الحج كالطواف والسعي؛ فلا بأس أن تحج عنه، جاء رجل إلى النبي ﷺ فقال: يا رسول الله، إن أبي شيخ كبير لا يستطيع الحج ولا الظعن، أفأحج عنه وأعتمر؟ قال: حج عن أبيك واعتمر، وجاءت امرأة وقالت: إن أبي شيخ كبير لا يثبت على الراحلة، أفأحجّ عنه؟ قال: حُجِّي عن أبيك. فإذا كان أبوك عاجزًا؛ لكبر سنه أو لمرضٍ لا يُرْجَى برؤه؛ فحج عنه -جزاك الله خيرًا- إذا كنتَ حججتَ عن نفسك، وإن لم تكن حججتَ عن نفسك فابدأ بالحج عن النفس أولًا، فتحُج عن نفسك ثم تحج عنه في عام آخر.[1]","link":"https://binbaz.org.sa/fatwas/31235/ما-حكم-الحج-عن-كبير-السن-العاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 056.mp3","categories":["النيابة في الحج"]},{"id":5988,"question":"وأخ يسأل فيقول: والدتي توفيت، ولم توص أحدًا بأن يحج عنها، هل يجوز لي أن أحج عن والدتي؟","title":"هل الحج عن الوالدة جائز؟","answer":"الجواب: نعم إذا كانت ما حجت تحج عنها الفريضة، وإذا كانت قد حجت فهو نافلة، وجزاك الله خيرًا، هذا من أهم البر، وقد سمعتم الحديث أن النبي ﷺ سأله رجل، فقال: هل بقي من بر والدي شيء أبرهما بعد وفاتهما، قال: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدها، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما.  فالحج عنهما من أفضل الأعمال، وإنفاذ عهدهما الوصية التي يوصيان بها إذا أوصيان بشيء تنفذ إذا كانت الوصية ما تخالف الشرع، تنفذ الصلاة عليهما، الدعاء لهما، وصلاة الجنازة، والاستغفار لهما.","link":"https://binbaz.org.sa/fatwas/1357/هل-الحج-عن-الوالدة-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_315.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":6392,"question":"من هم الأقارب الذين تجب صلة الرحم معهم، وتكون واجبة في حقهم؟","title":"تحديد الأقارب الذين يجب صلتهم","answer":"الجواب: كل الأقارب يوصلون، لكنهم يتفاوتون في القرب، فكل من كان أقرب؛ صارت صلته أوجب، فأقربهم الآباء، والأمهات، وإن علوا، والأولاد وأولاد البنين، والبنات، وإن نزلوا، ثم يليهم الإخوة، والأخوات، ثم بنو الإخوة، وبنات الإخوة، ثم الأعمام، والعمات، وهكذا. يقول النبي -عليه الصلاة والسلام- لما سئل، قال له رجل: أي الناس أحق بالصحبة وفي لفظ بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟  قال: أمك قال: ثم من قال: أبوك، ثم الأقرب فالأقرب وفي اللفظ الآخر: يا رسول الله من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من في الرابعة قال: أباك، ثم الأقرب، فالأقرب فهو مأمور بأن يبر والديه، ثم الأقرب، فالأقرب، كأولاده، وإخوته، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/1968/تحديد-الاقارب-الذين-يجب-صلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_755.mp3","categories":["النيابة في الحج","إهداء القرب للميت","فضائل الأعمال"]},{"id":6397,"question":"ما حكم من وكل في الرمي وهو يحج حجة الإسلام؟","title":"حكم التوكيل في الرمي في الحج","answer":"الجواب: إذا كان عاجزًا عن الرمي لمرض، أو صغر سن، أو ضعف بنية، أو لكونها امرأة لا تستطيع الزحام، أو مريضة، أو حبلى، أو ما أشبه ذلك من عذر؛ فالوكالة صحيحة، وأما إن كان قويًا بلا عذر؛ فلا تصح الوكالة، بل يرمي بنفسه.","link":"https://binbaz.org.sa/fatwas/1964/حكم-التوكيل-في-الرمي-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_751.mp3","categories":["النيابة في الحج"]},{"id":6943,"question":"موضوع الحديث عن البدع، فهل ينهي التوكيل، فبعضهم يقول: إنه من البدع؟","title":"حكم التوكيل في العبادات","answer":"الجواب: \nالتوكيل قسمان: عبادات فيها توكيل، وعبادات ما فيها توكيل، فالتوكيل في رمي الجمار، أو في ذبح الضحايا، ذبح الهدايا؛ لا بأس به، النبي وكل -عليه الصلاة والسلام- وكل عليًّا، فذبح بعض هديه -عليه الصلاة والسلام-والصحابة رموا عن أولادهم الصغار؛ لأنهم لا يستطيعون الرمي. وأما التوكيل كونه يصلي عنه، أو يصوم عنه لا، هذه ما فيها وكالات، يصوم بنفسه، ويصلي بنفسه، والعاجز عن الحج إذا عجز كبير السن، العاجز يخلي من يحج عنه، لا بأس.","link":"https://binbaz.org.sa/fatwas/2873/حكم-التوكيل-في-العبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1321.mp3","categories":["النيابة في الحج"]},{"id":7406,"question":"إني امرأة لي والدة توفيت قبل أن تحج حجة الإسلام، وأريد أن أوكل من يحج عنها من أحد أولادي، فهل يجوز ذلك، أم لا؟","title":"والدتي توفيت قبل أن تحج فهل لي أن أوكل من يحج عنها؟","answer":"الجواب: نعم نعم، إذا مات الرجل، أو المرأة قبل الحج، فحج عنه أهله بنته، أو ابنه، أو أحد أقاربه، أو غيرهم، أو استنابوا من يحج عنه من أهل الخير، فكل هذا طيب، وقد سئل النبي عن ذلك -عليه الصلاة والسلام- سأله إنسان فقال: إن أبي مات وعليه حجة الإسلام أفأحج عنه؟ قال: نعم، حج عن أبيك واعتمر، وامرأة سألته قالت: إن أبي شيخ كبير لا يثبت على الراحلة، أفأحج عنه؟ فقال: حجي عن أبيك وسأله آخرون عمن عليه حج، أو صيام؟ فأجاب بأنهم يحجون ويصومون عن ميتهم.","link":"https://binbaz.org.sa/fatwas/3504/والدتي-توفيت-قبل-ان-تحج-فهل-لي-ان-اوكل-من-يحج-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1808.mp3","categories":["النيابة في الحج"]},{"id":7421,"question":"إني امرأة لي والدة توفيت قبل أن تحج حجة الإسلام، وأريد أن أوكل من يحج عنها من أحد أولادي، فهل يجوز ذلك، أم لا؟","title":"والدتي توفيت قبل أن تحج فهل لي أن أوكل من يحج عنها؟","answer":"الجواب: نعم نعم، إذا مات الرجل، أو المرأة قبل الحج، فحج عنه أهله بنته، أو ابنه، أو أحد أقاربه، أو غيرهم، أو استنابوا من يحج عنه من أهل الخير، فكل هذا طيب، وقد سئل النبي عن ذلك -عليه الصلاة والسلام- سأله إنسان فقال: إن أبي مات وعليه حجة الإسلام أفأحج عنه؟ قال: نعم، حج عن أبيك واعتمر، وامرأة سألته قالت: إن أبي شيخ كبير لا يثبت على الراحلة، أفأحج عنه؟ فقال: حجي عن أبيك وسأله آخرون عمن عليه حج، أو صيام؟ فأجاب بأنهم يحجون ويصومون عن ميتهم.","link":"https://binbaz.org.sa/fatwas/3504/والدتي-توفيت-قبل-ان-تحج-فهل-لي-ان-اوكل-من-يحج-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1808.mp3","categories":["النيابة في الحج"]},{"id":7461,"question":"هذا السؤال يتعلق بالإنابة في الحج، مرسل الأسئلة من بلاد بلقرن، وهو الأخ محسن سالم محمد غزوان، يقول: دفع مال لشخص من أجل أن يحج لوالدته وهو يرى أنه أمين، ثم تبين له أن هذا الشخص يعمل عملاً غير صالح، ويطلب الإفادة في هذا؟","title":"حكم من أناب في الحج من ليس معروفاً بالصلاح والأمانة","answer":"الجواب: ينبغي لمن أراد أن يستنيب أحداً في الحج أو في العمرة أن يختار الرجل الصالح المعروف بالثقة والأمانة، ويسأل عنه ولا يتساهل، فلا يدفع المال إلى من لا يعرف حاله، بل الواجب أن يتثبت في الأمر، وألا يستنيب إلا الثقة الأمين الذي قد عرفه جيرانه وإخوانه وأصحابه بذلك، فإذا استأجر إنساناً ليس بأمين -يعني: إذا ظهر له بعد ذلك أنه ليس بأمين- فإن الأولى به ألا يكتفي بذلك إذا أحب، بل يدفع حجة أخرى إلى الثقة الأمين أو يحج بنفسه عن والدته أو عن جدته أو عن أخته في الله، عن أخته التي قد ماتت ولم تحج أو عاجزة لا تستطيع الحج لكونها كبيرة السن، يحج بنفسه هو، حتى يطمئن إلى أنه أدى الحجة عن هذه القريبة، أو يعطيها إلى ثقة أمين معروف؛ حتى يطمئن إلى أنه يؤديها كما شرع الله .\nوكثير من الناس لا يبالي، يدفع الحجة إلى كل أحد، إلى من هب ودب، هذا غلط، لا ينبغي هذا، وليس من الأمانة، وليس من الرعاية، فلابد من أن يكون الإنسان يرعى الأمانة ويتقي الله في شئونه كلها.\nفالحاصل: أنه إذا تيسر له أن يحج بنفسه عن أمه أو جدته أو أخته فلا بأس وهذا أولى، وإن لم يتيسر اختار الثقة الأمين المعروف بالديانة والأمانة، وإذا تيسر أنه من أهل العلم كان هذا أكمل؛ حتى يؤدي الأنساك على خير وجه وعلى ما شرعه الله .\nثم الحج لا يكون إلا عن ميت أو عن إنسان كبير السن -أي: عاجز عن الحج- أما الصحيح الحي لا يحج عنه، بل إنما يكون عن الميت أو الذي عجز لكبر سنه أو مرضه الذي لا يرجى برؤه يحج عنه، حتى ولو النافلة على الأرجح. نعم.\n  المقدم: ولكن الآن الحجة وقعت وهو يسأل عن حكمها هل..؟\nالشيخ: الظاهر الإجزاء إن شاء الله، إذا كان لا يدري هل حج أو ما حج فالظاهر الإجزاء؛ لأن الأصل أن مثل هذه المسائل الغالب على من أخذها أنها يؤديها، هذا الغالب، وإن كان قد يتهم بالخيانة لكن الغالب أنه يؤديها؛ لكن إذا احتاط وأخذ حجة أخرى من باب الاحتياط، هذا حسن، من باب دع ما يريبك إلى ما لا يريبك ومن باب الحيطة، ولاسيما إذا كان وكيلاً في ذلك، إذا كان وكيلاً في إخراج الحجة فقد قصر في الوكالة ولم يعتن بها، فكونه يخرج من ماله حجة أخرى ليحتاط لدينه ولبراءة ذمته هذا يكون أولى إن شاء الله؛ لأن ذاك الأول غير مأمون على أداء الحجة. نعم.","link":"https://binbaz.org.sa/fatwas/4179/حكم-من-اناب-في-الحج-من-ليس-معروفا-بالصلاح-والامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00103.mp3","categories":["النيابة في الحج"]},{"id":7533,"question":"سؤاله الآخر يقول: هل يجوز أداء العمرة عن والدي المتوفى، وتكليف شخص آخر بتأدية الفريضة عنه؟","title":"التوكيل في الحج والعمرة","answer":"الجواب: لا بأس بذلك، لا بأس أن يؤدي العمرة عن والده، ويكلف شخصاً ثقة يؤدي عنه الحج، لا بأس بذلك، وإن تولى بنفسه أداء العمرة والحج عن والده فهذا أكمل في البر، ويجوز أن يؤدي الحج عن والده شخص غيره وهو يؤدي العمرة.\nكما يجوز أن يحج عن شخص ويعتمر عن شخص آخر، كل هذا لا بأس به. نعم.","link":"https://binbaz.org.sa/fatwas/4519/التوكيل-في-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01103.mp3","categories":["النيابة في الحج"]},{"id":7535,"question":"هذه الرسالة من سلمان الطاوي العنزي: يسأل أيضاً عن الحج يقول: إن لي زوجة وقد توفيت ولم تقض فريضة الحج، وأنا أريد أن أحج عنها أقض غير أنني لم أقضي فريضة الحج عن نفسي، وما أدري هل يجوز لي أن أنيب واحداً يحج عنها؟ وهل يجوز لي أن أنيب واحداً يحج عني، أفيدوني أثابكم الله؟","title":"الحج عن الغير لمن لم يحج عن نفسه","answer":"الجواب: أما الميتة فجزاه الله خيراً إن استناب ليحج عنها من الثقات الطيبين، وإن أخر ذلك حتى يحج عن نفسه ثم يحج عنها فلا بأس، أولاً يحج عن نفسه، يبدأ بنفسه أولاً، هذا هو الواجب، ثم يحج عنها إذا شاء بعد ذلك، وإن أحب أن يعجل حجها فيعطي بعض الثقات مالاً يحج عنها فلا بأس، كله طيب.","link":"https://binbaz.org.sa/fatwas/4521/الحج-عن-الغير-لمن-لم-يحج-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01106.mp3","categories":["النيابة في الحج"]},{"id":7849,"question":"أيضاً يقول: هل يجوز لمن اعتمر عن غيره بالأجر أن يحج لنفسه؟","title":"حكم من اعتمر عن غيره وحج نفسه والعكس","answer":"الجواب: لا حرج، إذا اعتمر الإنسان عن غيره له أن يحج عن نفسه، أو اعتمر لنفسه له أن يحج عن غيره إذا كان قد حج عن نفسه، الحاصل أنه إذا كان قد اعتمر عن نفسه وحج عن نفسه لا بأس أن يحج عن غيره من الأموات أو العاجزين لكبر السن يحج عنهم من أقاربه وأمواته أو غيرهم لا بأس، المهم أنه لا يحج عن أحد إلا بعد أن يحج عن نفسه، ولا يعتمر عن أحد إلا بعد أن يعتمر عن نفسه، والحج مرة في العمر والعمرة مرة في العمر، وما زاد بعد هذا فهو سنة وتطوع، فإذا اعتمر الإنسان عن غيره عن أمه أو أبيه في أشهر الحج ثم حج عن نفسه فهو متمتع، أو اعتمر لنفسه ثم حج عن غيره فهو متمتع في عام واحد إذا كانت العمرة في أشهر الحج.","link":"https://binbaz.org.sa/fatwas/5245/حكم-من-اعتمر-عن-غيره-وحج-نفسه-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05402.mp3","categories":["النيابة في الحج"]},{"id":7850,"question":"هذه رسالة من المستمع راشد بن أحمد الراشد يقول فيها: إذا ناب شخص عن مسلم بعمرة وعن آخر بحج، فهل يجوز له ذلك بإذنهما علماً أنه قد اعتمر وحج عن نفسه سابقاً؟!","title":"حكم من حج عن غيره واعتمر عن آخر بإذنهما","answer":"الجواب: مثلما تقدم لا حرج أن يكون معتمراً عن زيد وحاجاً عن عمرو، يعتمر عن زيد ويحج عن عمرو، يعتمر عن أمه ويحج عن أبيه، يعتمر عن أخيه ويحج عن أخته وهكذا، وهو متمتع في هذا كله مادام أدى العمرة والحج في عام واحد في أشهر الحج فهو متمتع مطلقاً، سواء كانت الحجة والعمرة عن نفسه أو عن غيره، أو هذه عن واحد والأخرى عن واحد كله سواء، يسمى متمتعاً وعليه الهدي المشروع واحد فدية واحدة، سبع بدنة، أو سبع بقرة، أو ثني من المعز، أو جذع من الضأن، هذه الهدية المشروعة في حق المتمتع والقارن. نعم.\nالمقدم: لكن بالنسبة للهدي -يا سماحة الشيخ- على من يكون؟\nالشيخ: عليه هو، على الذي فعل الحج والعمرة، سواء متطوعاً عن غيره أو بالأجرة. نعم.\nالمقدم: لكن.\nالشيخ: هو اللي باشر الأمر.\nالمقدم: هو الذي باشر الأمر، لكن في هذه الحالة هو ليس له لا حج ولا عمرة؟\nالشيخ: لا، هو يرجى له الأجر إذا كان له نية صالحة إن شاء الله يرجى له الشركة في الخير.\nالمقدم: لكن لا يلزم .....\nالشيخ: ولها طوافات كثيرة يطوفها لنفسه، وصلوات، وعبادات يفعلها هو على خير إن شاء الله مع النية الصالحة.\nالمقدم: الحقيقة: يتردد في أوساط عامة المسلمين أن الإنسان إذا حج أو اعتمر عن شخص بالأجر أن جميع ما يفعله عدا الصلاة والأشياء التي كان يفعلها في بلده كلها تنصرف لمن حج عنه أو اعتمر.\nالشيخ: المعروف إنه يكون للمحجوج عنه ما يتعلق بالحج، طوافه.. سعيه.. رمي الجمار، كل ما يتعلق بواجبات الحج وأركانه، هذه تكون للحاج، وأما هو يرجى له أن يكون مثل أجره إذا نوى، إذا كان له نية صالحة يرجى له أن يكون مثل أجره، وكذلك ما يطوف لنفسه من الطوفات المتطوع بها في مكة هذا أيضاً له أجره، كذلك صلواته في مكة، صدقاته، تسبيحه، تهليله، كل هذا له، ما للمحجوج عنه سنن، المحجوج عنه له أمور الحج وواجبات الحج وأركان الحج هذه له، وقد يكون له أجر السنن أيضاً، قد يكون له أجر السنن المتعلقة بالسنن مثل ركعتي الطواف، مثل ما يفعل في السعي والطواف من الأذكار، قد يكون للحاج أجر ذلك، وله هو مثل أجره أيضاً، قد يكون هذا لأن هذا تابع للطواف والسعي، الأذكار والدعوات التي فيها أجرها تابع للطواف والسعي، فقد يكون للمحجوج عنه لأنه من تبع الطواف والسعي، وقد يكون أجر ذلك للحاج النائب لأنه متطوع لأن الذكر ما هو بواجب والدعاء ما هو بواجب، محتمل، وبكل حال فهو على خير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/5247/حكم-من-حج-عن-غيره-واعتمر-عن-اخر-باذنهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05403.mp3","categories":["النيابة في الحج"]},{"id":7851,"question":"أيضاً يقول راشد بن أحمد الراشد من الدمام في المنطقة الشرقية، يقول في رسالته هذه: إذا أناب المعضوب أو المعذور من يحج عنه، وبعد أن أحرم بالحج وتلبس به شفي المعذور، فهل يقع هذا -يعني: هذا الحج- عن المعذور، وهل يقع حجة الإسلام، أم يكون نفلاً في حقه؟","title":"حكم من أناب شخصاً ليحج عنه لعذر ثم زال العذر","answer":"الجواب: هذا فيه خلاف بين أهل العلم، ويؤجل حتى نجيب عنه في حلقة أخرى إن شاء الله في هذه المسألة خلاف بين أهل العلم، نجيب عنه إن شاء الله في حلقة أخرى بعد المراجعة والعناية بالأمر. نعم.","link":"https://binbaz.org.sa/fatwas/5248/حكم-من-اناب-شخصا-ليحج-عنه-لعذر-ثم-زال-العذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05404.mp3","categories":["النيابة في الحج"]},{"id":8067,"question":"هذا السؤال مرسله المستمع جابر علي عبد الله هزازي ، والجميع في ورقة واحدة، يقول  والدي توفي وما قام بتأدية الحج، فهل يجوز قضاء الحج عنه أم لا؟","title":"حكم الحج عن الوالد المتوفى","answer":"الجواب: إن كان غنياً وجب أن يقضى من ماله الحج، وإن كان معسراً فلا شيء عليه، لكن إذا حججت عن أبيك هذا طيب وهذا من البر، إذا حججت عن أبيك ولو كان فقيراً، إذا حججت عنه فقد أحسنت وهذا من البر، تحج عنه وتعتمر، أما إن كان غنياً ولكن تساهل فالواجب أن يحج عنه، إن حججت عنه من نفسك فجزاك الله خيراً، وإن لم تحج عنه فلابد من إخراج مال يعطاه من يحج عنه من الثقات الأمناء الأخيار. نعم.","link":"https://binbaz.org.sa/fatwas/5864/حكم-الحج-عن-الوالد-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08309.mp3","categories":["النيابة في الحج"]},{"id":8233,"question":"ما هي العبادات التي يجوز فيها النيابة مع بيان شروط النيابة للكل؟","title":"العبادات التي يجوز فيها النيابة والتوكيل","answer":"الجواب: العبادات التي فيها النيابة أنواع: منها الحج، ومنها العمرة، ومنها توزيع الزكاة، كونه يستأجر الثقة يوزع الزكاة، ويستأجر ثقة يحج عنه إذا كان عاجزاً كالشيخ الكبير العاجز والعجوز الكبيرة، والمريض الذي لا يرجى برؤه، وهكذا في العمرة، وهكذا توزيع الكفارات، يستأجر من يوزع عنه كفارة وطئه في رمضان، أو كفارة ظهاره، إذا كان عاجز عن العتق والصيام وكل من يوزع عنه إطعام ستين مسكين، وهكذا يوكل لشراء الرقبة التي عليه في وطء رمضان، أو في تحريمه زوجته، أو في القتل، هذه كلها من العبادات التي فيها النيابة. نعم.","link":"https://binbaz.org.sa/fatwas/6043/العبادات-التي-يجوز-فيها-النيابة-والتوكيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09702.mp3","categories":["النيابة في الحج"]},{"id":8387,"question":"يسأل أخونا سؤال آخر، ويقول: إن والدتي عمرها خمس وستون سنة، وزوجتي ست وعشرون سنة، وتقيمان في تونس، أوصتا بأن أعتمر مكانهما، فهل يجوز ذلك؟","title":"حكم الاعتمار عن الوالدة والزوجة مع القدرة وعدمها","answer":"الجواب: ليس لك أن تعتمر عنهما، بل عليهما أن يعتمرا إذا أعانهما الله على ذلك ويسر لهما ذلك، لكن لو كانت أمك عاجزة لكبر السن لا تستطيع الحج والعمرة، فلك أن تعتمر عنها وتحج عنها إذا كانت عاجزة؛ لأن الرسول ﷺ سئل، سألته امرأة، فقالت: يا رسول الله! إنن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عن أبيك فإذا كانت أمك عاجزةً لا تستطيع الحج ولا العمرة، فإنك تعتمر عنها وتحج عنها، ولا بأس.\nوهكذا لو كانت الأم ميتة، أو الأب ميت، لا بأس أن تحج عنهما وتعتمر. نعم.","link":"https://binbaz.org.sa/fatwas/6253/حكم-الاعتمار-عن-الوالدة-والزوجة-مع-القدرة-وعدمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11606.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":8397,"question":"يقول: أريد أن أؤدي فريضة الحج عن خالي، هل لي أن أستشير أبناءه الصغار؟","title":"حكم استشارة أبناء الميت في الحج عن أبيهم","answer":"الجواب: إذا كان خالك متوفى وأنت قد أديت الفريضة فلا بأس أن تؤدي الحج عنه، ولا حاجة إلى استشارة أحد لا أبناءه ولا غير أبناءه، بهذا الشرط إذا كان قد توفي، أو كان كبير السن لا يستطيع الحج، وأنت قد أديت الفريضة، فإنك إذا أحسنت إليه بأداء الحج عنه فأنت مشكور ومأجور، ولا حاجة إلى استئذان أحد.","link":"https://binbaz.org.sa/fatwas/6263/حكم-استشارة-ابناء-الميت-في-الحج-عن-ابيهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11702.mp3","categories":["النيابة في الحج"]},{"id":8636,"question":"يقول في رسالته أيضاً: هل الحج عن والدي بعد موته يجوز أم لا؛ لأنني وهبت حجة لوالدي رحمه الله بعد وفاته، أفيدوني أفادكم الله؟","title":"حكم الحج عن القريب المتوفى","answer":"الجواب: نعم، لا مانع أن تحجي عن والدك، وعن جدتك، وعن أمك لا بأس، وعن أخيك بعد وفاته، هذا من البر والصلة، وهكذا بعد العجز إذا كان عاجز كبير السن لا يستطيع الحج، وهكذا الوالدة إذا عجزت وحججت عنها كل ذلك طيب. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6783/حكم-الحج-عن-القريب-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21210.mp3","categories":["النيابة في الحج"]},{"id":8746,"question":"أفيد فضيلتكم بأني أعمل بالمملكة وأهلي في السودان، هل يجوز أن أقوم بمناسك العمرة عن والدي ووالدتي نيابة عنهما، علمًا بأنهما أقوياء ويقدرون على العمرة؟","title":"حكم أداء الحج والعمرة عن الوالدين القويين المستطيعين","answer":"الجواب: ليس لك ذلك، ما دام والداك قويين فهما يحجان بأنفسهما ويعتمران بأنفسهما، وأنت تحج عن نفسك وتعتمر عن نفسك، أما لو كانا ميتين أو عاجزين لا يستطيعان الحج ولا العمرة فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6898/حكم-اداء-الحج-والعمرة-عن-الوالدين-القويين-المستطيعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16208.mp3","categories":["النيابة في الحج"]},{"id":8792,"question":"السؤال الثالث في رسالة الأخ عباس جداح الجنابي ، يقول فيه: في نيتي الذهاب إلى بيت الله الحرام لأؤدي فريضة الحج بمشيئة الله للمرة الثانية، فهل أستطيع أن أكلف أحداً من المسلمين بأن يؤدي الفريضة بدلاً عن والدي المتوفى في نفس العام، أفيدوني أفادكم الله؟","title":"حكم الحج عن المتوفى","answer":"الجواب: لا مانع من ذلك أن تحج عن والدك من المسلمين الذين في مكة، لا مانع أن تعطي من تراه ثقةً، أو طيب الدين، موثوقاً به في عمله، تعطيه ما تيسر من المال حتى يحج عن والدك؛ لكن يحرم من الحل، لا من نفس مكة للعمرة؛ أما في الحج فيحرم من نفس مكة لا بأس، ولا حاجة إلى أن يذهب إلى الميقات في أصح قولي العلماء، فيحرم من مكة بالحج، وأما العمرة فيحرم بها من الحل من الجعرانة أو من التنعيم أو غيرهما من الحل، يعني: خارج مكة، خارج الحرم، هذا في العمرة خاصة، أما في الحج فيحرم من مكة من الحل أو الحرم لأبيك، إذا كان ثقةً طيباً، والله ولي التوفيق. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6945/حكم-الحج-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22008.mp3","categories":["النيابة في الحج"]},{"id":8801,"question":"السؤال الرابع في رسالة الأخ سعد يقول فيه: إذا مات أحد أصدقائي هل يجوز لي أن أقوم عنه بزيارة مسجد الرسول ﷺ بالمدينة المنورة، وهل يجوز أن أقوم عنه بالعمرة أفيدونا جزاكم الله خيراً؟","title":"حكم التوكيل في العمرة وزيارة المسجد النبوي","answer":"الجواب: نعم لا حرج عليك أن تحج عن أخيك محبك في الله أو أبيك أو أمك أو نحو ذلك من الأموات، لا حرج عليك أن تحج عنه أو تعتمر هذا كله مشروع ولك في هذا أجر وللميت أجر.\nأما النيابة.. أما الزيارة عنه للمسجد فلا نعلم له أصلاً الزيارة كونك تنوب عنه هذا من الأعمال البدنية التي لم يرد فيها ما يدل على شرعية النيابة، وهكذا الصلاة لا تصل عنه ولا تزور عنه المسجد النبوي، بل هذا شيء يختص بالإنسان ولا ينوب فيه عن غيره.\nلكن تزوره لنفسك تزور المسجد تصلي فيه تسلم على النبي ﷺ وتسلم على صاحبيه، تزور البقيع تسلم عليهم، تزور الشهداء تسلم عليهم، تزور مسجد قباء وتصلي فيه هذا كله طيب لنفسك.\nأما أن تنوب عن غيرك في هذه الزيارة هذا غير مشروع فيما نعلم، وإنما تزور مسجد الرسول ﷺ لتصلي فيه ؛ لأن الصلاة فيه مضاعفة، يقول عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام وزيارة القبور سنة، فإذا زرت المسجد زرت قبره ﷺ وقبر صاحبيه وسلمت عليه وعلى صاحبيه عليه الصلاة والسلام ورضي الله عنهما، ويشرع لك أيضاً أن تزور البقيع تسلم على أهل البقيع من الصحابة ومن فيه من غيرهم، ويستحب لك أن تزور أيضاً قبور الشهداء وتسلم عليهم، ويستحب لك أن تزور مسجد قباء تصلي فيه ركعتين أو أكثر كل هذا مشروع، لكن لا تنوب في هذا عن غيرك بل تفعله عن نفسك، هذا هو المشروع. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6959/حكم-التوكيل-في-العمرة-وزيارة-المسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22206.mp3","categories":["النيابة في الحج"]},{"id":9048,"question":"السؤال الثاني في رسالة الأخت: صالحة محمد علي أبو حسين من مكة المكرمة تقول فيه: هل يجوز للمرأة أن تحج عن امرأة أو رجل من أقاربها أو من جيرانها؟ أفيدونا أفادكم الله.","title":"حكم حج المرأة عن غيرها","answer":"الجواب: لا حرج أن تحج المرأة عن امرأة مثلها أو عن رجل كأبيها وأمها وخالها وخالتها ونحو ذلك، أو شخص تحبه في الله إذا كان قد توفي، أو كان عاجزاً لكونه شيخاً كبيراً أو لكونها عجوزاً كبيرة لا تستطيع الحج، فلا بأس أن يحج المؤمن عن هؤلاء، حج المرأة عن امرأة أو عن رجل سواء كان ميتاً أو كان حياً لكنه عاجز لا يستطيع الحج، لكبر سنه أو لأنه مصاب بمرض لا يرجى برؤه لا يستطيع معه الحج، فلا بأس أن يحج عنه رجل أو امرأة، عن الميت وعن الحي العاجز، وقد جاءت امرأة من خثعم إلى رسول الله صلى الله عليه وسلم فقالت يا رسول الله إن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عنه، وجاءه رجل آخر، وجاء رجل فقال: يا رسول الله! إن أبي لا يستطيع الحج ولا العمرة ولا الظعن أفأحج عنه؟ قال: حج عن أبيك واعتمر فلا حرج في هذا الأمر، سواء كان المحجوج عنه قريباً أو ليس بقريب ممن يحب في الله، ويريد أخوه في الله أن يؤدي عنه الحجة. نعم.","link":"https://binbaz.org.sa/fatwas/7204/حكم-حج-المراة-عن-غيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22404.mp3","categories":["النيابة في الحج"]},{"id":9050,"question":"الرسالة الأولى وصلت إلى البرنامج من المستمع: عادل عبدالحميد حسن من جمهورية مصر العربية، ومقيم في الأردن، يقول في سؤاله الأول: توفي والدي ولم يحج إلى بيت الله الحرام، وأنا أريد أن أحج حجة أوهبها له، فهل يجوز أن أحج عنه أم لا؟ أفيدوني أفادكم الله.","title":"حكم الحج عن الغير","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فلا بأس في أن تحج عن أبيك، فقد ثبت عن النبي ﷺ أنه سأله غير واحد بعضهم يقول: إن أبي لا يستطيع الحج، أفأحج عنه؟ والآخر يقول: إن أمي ماتت ولم تحج أفأحج عنها؟ فيجيبهم ﷺ بالإذن في ذلك، فلك يا أخي أن تحج عن أبيك مرة أو أكثر، وأنت في هذا مشكور وهذا من بره والإحسان إليه بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/7199/حكم-الحج-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22401.mp3","categories":["النيابة في الحج"]},{"id":9068,"question":"هذه رسالة وصلت إلى البرنامج من المستمع حسين بن علي السامرائي من العراق الموصل، يقول في رسالته: لقد توفيت والدتي قبل أن تؤدي فريضة الحج، فهل أنا ملزم بالحج عنها بعد أن وفقني الله بأداء هذه الفريضة عن نفسي؟ وهل يمكنني تكليف شخص آخر بالحج عن والدتي أرجو إفادتي عن حكم الشرع في مسألة الحج عن الغير بصفة عامة، أفيدونا أفادكم الله؟","title":"حكم حج الولد عن أمه بنفسه أو تكليف غيره","answer":"الجواب: إذا كانت والدتك تستطيع الحج في حياتها؛ لأنها ذات مال، فإنك تحج عنها ثقة من الطيبين، أو تحج عنها بنفسك وذلك أفضل؛ لأنك ولدها وأقرب الناس إليها، فإذا حججت عنها بنفسك، فذلك أفضل إذا تيسر لك ذلك، وإن حجيت عنها بواسطة بعض الثقات الطيبين فلا بأس، وهذا واجب إذا كانت في حال حياتها مستطيعة، فالواجب أن يحج عنها من مالها، أو من نفسك من دون النظر إلى مالها من باب الإحسان إليها والبر بها، فأنت مخير إن شئت أخرجت من مالها، وإن شئت حججت عنها من نفسك بنفسك أو من مالك بواسطة الثقة الطيب المعروف بالديانة والخير والأمانة.\nوالحج عن الغير مشروع، وهل يجب إذا كان الغير توفي ولم يحج وهو مستطيع؟ وجب أن يحجج عنه من ماله، أما إن كان لم تجب عليه الحجة؛ لأنه فقير، فإن حج عنه أحد فلا بأس، وإن حج الإنسان عن أبيه أو عن أمه العاجزين فهذا مشروع وطيب ومن البر، لكن لا يجب عليك أن تحج عن أبيك ولا عن أمك، إلا إذا كانا قادرين في حياتهما على الحج فتساهلا، فإنك تخرج من مالهما لمن يحج عنهما من الثقات الطيبين، أو تحج عنهما بنفسك، وأما إذا كانا قد حجا أو كانا غير مستطيعين للحج، فإنه يشرع لك أن تحج عنهما ولا يجب عليك، بل هذا من برهما. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7230/حكم-حج-الولد-عن-امه-بنفسه-او-تكليف-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22502.mp3","categories":["النيابة في الحج"]},{"id":9230,"question":"هذه رسالة وصلت إلى البرنامج من المستمع مكاوي أحمد محمد من جمهورية مصر العربية، يقول في رسالته: هل يصح لي أن أقوم بأداء العمرة عن والدتي المتوفية، حيث أني قد أديت العمرة عن نفسي في رمضان هذا العام، وهل يصح لي أن أقوم بأداء العمرة عن والدتي بعد أداء فريضة الحج، أو قبل أدائي لفريضة الحج، أفيدونا أفادكم الله؟","title":"حكم أداء العمرة عن المتوفى","answer":"الجواب: نعم، لا بأس بذلك، بل أنت مأجور، ومشروع لك أن تحسن إلى والدتك بالعمرة قبل الحج أو بعده، وإذا كنت في مكة تحرم من الحل، يعني: خارج مكة، خارج الحرم، من مساجد عائشة التنعيم، أو من الجعرانة، أو غيرهما من الحل، كما أمر النبي ﷺ عائشة رضي الله عنها لما أرادت العمرة بعد الحج أن تحرم من الحل من التنعيم، هكذا السنة فيمن كان في مكة إذا أراد العمرة لنفسه أو لغيره؛ أن يخرج إلى الحل ثم يلبي بعمرة هناك، ثم يدخل فيطوف سبعة أشواط بالبيت ويصلي ركعتين خلف المقام، أو في أي بقعة من المسجد، ثم يسعى بين الصفا والمروة سبعة أشواط، ثم يقصر من رأسه، هكذا العمرة، وأنت مأجور في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7390/حكم-اداء-العمرة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23310.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":9348,"question":"من بغداد رسالة بعثت بها إحدى الأخوات المستمعات، الواقع الرسالة من صفحتين ملخصها أن عمة لهم قامت بتربيتهم تربية حسنة تثني عليها، وتسأل في النهاية إذا كانت عمتهم قد أدت فريضة الحج هل لهم أن يحجوا عنها أيضًا؟ وتسأل عن حديث رسول الله ﷺ: إذا مات الإنسان انقطع عمله إلا من ثلاث .. وهل المراد بالولد الصالح الولد الذي من نفس الشخص، أو الولد الذي تربى على يد مربيه كما فعلت تلكم العمة؟","title":"حكم الحج عن القريب المتوفى أو العاجز","answer":"الجواب: أولًا: يشرع لهم الدعاء لها، والترحم عليها، والصدقة عنها في مقابل إحسانها إذا كانت مسلمة، يدعون لها، ويترحمون عليها، ويتصدقون عنها؛ لأنها أحسنت، والله يقول: هَلْ جَزَاءُ الإِحْسَانِ إِلَّا الإِحْسَانُ [الرحمن:60] فالمحسن ينبغي أن يجازى ويكافأ، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: من صنع إليكم معروفًا فكافئوه؛ فإن لم تجدوا ما تكافئوه فادعوا له حتى تروا أنكم قد كافأتموه فهي محسنة فيشرع لهما أن يحسنا إليها وأن يتصدقا عنها، وأن يدعوا لها، والحج من ذلك، إذا حجوا عنها وهي ميتة أو عاجزة ما تستطيع الحج لكبر سنها، فإن الحج عنها ينفعها، هذا من القرب العظيمة.\nأما الولد الذي يدعو للإنسان فهذا المراد به ولده نفسه، ولد صلبه إذا دعا له فهذا مما ينفعه؛ ولهذا قال: أو ولد صالح يدعو له يعني: ولد الميت نفسه، وأولاد بناته، وأولاد أولاده من ولده، إذا دعا له أولاد أولاده وأولاد بناته وأولادهم وإن نزلوا كلهم داخلون في هذا. نعم.","link":"https://binbaz.org.sa/fatwas/7504/حكم-الحج-عن-القريب-المتوفى-او-العاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18504.mp3","categories":["النيابة في الحج"]},{"id":9713,"question":"السؤال الثاني في رسالة الأخ عبدالسلام يقول فيه: هل يصح للإنسان الذي لم يحج عن نفسه أن يحج عن إنسان آخر له دين عليه علمًا بأن هذا الذي سوف يقوم بالحج عن صاحب الدين قد عمل له سند بالدين الذي عليه، فهل يصح هذا أفتونا مأجورين وجزاكم الله عنا خير الجزاء؟","title":"الحج عن الغير قبل الحج عن النفس","answer":"الجواب: ليس للإنسان أن يحج عن غيره قبل أن يحج عن نفسه، هذا هو الصواب من قول أهل العلم ولكن يبدأ بنفسه فيحج عنها ثم بعد ذلك لا حرج أن يحج عن غيره إذا قصد بذلك خيرًا وأراد أن يشارك في الحج والمشاعر العظيمة ويشارك المسلمين في الخير وأخذ ما يستعين به من المال حتى يحج عن غيره لا بأس لكن لابد أن يبدأ بنفسه لابد أن يحج أولًا فإذا حج أولًا فلا بأس أن يحج عن غيره، وإذا حج عن نفسه كان أولى وأفضل إلا إذا أخذ المال ليحج عن غيره بقصد صالح بقصد أداء الحق الذي في ذمة أخيه من الحج أو لقصد المشاركة في الخير والحرص على الوصول إلى المشاعر وهو لا يستطيع ذلك فيستعين بأخذ المال ليحج عن غيره حتى يشاركه في الخير فهذا عمل صالح. نعم.","link":"https://binbaz.org.sa/fatwas/7867/الحج-عن-الغير-قبل-الحج-عن-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19505.mp3","categories":["النيابة في الحج"]},{"id":10071,"question":"أحد الإخوة المستمعين بعث يسأل ويقول: هل يجوز للإنسان أن يحج لغيره قبل حجته جزاكم الله خيراً؟","title":"حكم من حج عن غيره قبل أن يحج عن نفسه","answer":"الجواب: ليس للإنسان أن يحج عن غيره إلا بعد أن يحج، كما صح بهذا الخبر عن رسول الله ﷺ، أنه سمع رجلاً يقول: لبيك عن شبرمة فقال: من شبرمة ؟، قال له النبي ﷺ: من شبرمة قال: أخ لي أو قريب لي، قال: حججت عن نفسك؟ قال: لا، قال: حج عن نفسك ثم حج عن شبرمة، لكن لو أخرج مالاً لبعض الناس يحج به لا بأس، أما أن يحج بنفسه لا ليس له الحج بنفسه.. قبل أن يحج ليس له أن يحج عن غيره بنفسه قبل أن يحج عن نفسه، بل يبدأ بنفسه فيحج، أما لو أعطى إنساناً مالاً قال: حج عن أبي أو أخي فلا حرج فلا حرج في هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8240/حكم-من-حج-عن-غيره-قبل-ان-يحج-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30403.mp3","categories":["النيابة في الحج"]},{"id":10102,"question":"أنا أديت فريضة الحج متمتعًا بالعمرة والحمد لله، ووالدي قد توفي وأريد أن أحج له، فكيف توجهونني وفقكم الله؟","title":"حكم الحج عن الوالد","answer":"الجواب: أنت مأجور بالحج عنه جزاك الله خير، مأجور في الحج عنه يشرع لك أن تحج عنه إذا كان ما حج فريضته يشرع لك أن تحج عنه، وإن كان قد حج فلا بأس أن تحج عنه نافلة، أنت مأجور على كلٍ ولك مثله، لك من الأجر مثلما يكون لأبيك، وأنت على خير إن شاء الله، نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8274/حكم-الحج-عن-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27703.mp3","categories":["النيابة في الحج"]},{"id":10128,"question":"الأخت صالحة رسام من مدينة حائل بعثت تقول: إنها امرأة متزوجة منذ ثلاث سنوات تقريباً وذهبت إلى الحج في عام ألف وأربعمائة وسبعة علماً بأنها أول سنة تحج فيها، وتسأل إذ أني لم أرم الجمرات في هذا الحج أبداً، لأن زوجي قال لي: وكليني لأرمي عنك، فوكلته خوفاً من الزحام، هل علي شيء أفيدوني مأجورين جزاكم الله خيراً؟","title":"حكم من حجت ووكلت زوجها بالرمي عنها لشدة الزحام","answer":"الجواب: ليس عليك شيء؛ لأن الزحام الشديد الذي يخشى منه الخطر على المرأة وعلى الضعيف عذر في التوكيل، وإن اشتبه عليك الأمر وخفت أن يكون هناك تقصير فاذبحي ذبيحة عن ترك الرمي تذبح في مكة كالضحية، يعني: رأس من الغنم جذع ضأن أو ثني معز كالضحية يذبح في مكة، توكلين ثقة في مكة يذبحها عنك احتياطاً عن ترك الرمي، أما إن كانت الزحمة شديدة ولم تستطيعي الرمي ووكلتيه فلا حرج عليك والحمد لله.\nالمقدم: جزاكم الله خيراً، أيضاً حول نفس الموضوع تقريباً تقول: ذهبت أيضاً للحج في عام ألف وأربعمائة وتسعة وهذا الحج لوالدتي المتوفاة، ورميت جميع الجمرات إلا الجمرة الأخيرة بسبب الزحام وكلت زوجي فرماها، أرجو إفادتي بارك الله فيكم إذا كان علي دم هل يجوز أو أن توكيل الزوج ليس فيه شيء، جزاكم الله خيرا؟\nالشيخ: ليس عليك حرج إذا كان الزحام شديداً فيه الخطر فالوكالة لا بأس بها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8298/حكم-من-حجت-ووكلت-زوجها-بالرمي-عنها-لشدة-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30504.mp3","categories":["النيابة في الحج"]},{"id":10139,"question":"بعد هذا رسالة يقول صاحبها: أنا عامل بالحلوة محافظة حوطة بني تميم، والدي توفي وهو فقير ولم يحج حجة الإسلام، وأنا ذو عائلة ومتوسط الحال، هل أحج عنه من نفقة عيالي أم لا؟ أفيدوني بارك الله فيكم.","title":"حكم الحج عن الأب الذي لم يحج لعدم الاستطاعة","answer":"الجواب: إذا مات وهو فقير ليس عليه حج؛ لأن الله يقول: مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]، فإذا كان والدك توفي وهو عاجز عن الحج فليس عليه شيء، وأنت كذلك ليس عليك شيء، إذا كانت النفقة التي عندك قليلة بقدر نفقة العائلة فليس عليك حج حتى أنت.\nأما إذا تيسر أن تحج عنه من مال ميسور بعد حجك عن نفسك هذا من البر، وقد سئل النبي ﷺ، سأله رجل قال: يا رسول الله! إن أبي توفي ولم يحج، أفأحج عنه؟ قال: حج عن أبيك، وسأله آخر: سألته امرأة قالت: يا رسول الله! إن أبي شيخ كبير لا يستطيع أن يثبت على الراحلة أفأحج عنه؟ قال: حجي عن أبيك، وسأله آخر، قال: إن أبي لا يستطيع الحج ولا الضعن أفأحج عنه؟ قال: حج عن أبيك واعتمر، كل هذا من البر، فإذا كنت تستطيع فإنك يشرع لك أن تحج عنه بعد حجك عن نفسك، أما إذا كنت لا تستطيع فلا يكلف الله نفساً إلا وسعها.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8310/حكم-الحج-عن-الاب-الذي-لم-يحج-لعدم-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27712.mp3","categories":["النيابة في الحج"]},{"id":10206,"question":"من الدمام إحدى الأخوات تقول: المرسلة (ب. الدوسري ): تسأل وتقول: سماحة الشيخ! والدتي لم تحج حتى الآن، وهي غير مستطيعة، فهل يجوز لزوجي أن يؤدي الحج عنها، علماً بأنه مستطيع وراضٍ بذلك، وجهونا جزاكم الله خيرًا؟","title":"حكم الحج عمن عجز عنه بدنيا","answer":"الجواب: إن كانت تستطيع ببدنها لا يحج عنها، متى استطاعت حجت وإلا فلا شيء عليها، حتى تموت أو تعجز من جهة البدن، أما إن كانت عاجزة من جهة أنها هرمة عجوز كبيرة يشق عليها الحج أو ميتة يحج عنها، أما امرأة قوية لكن ما عندها مال ما عليها حج حتى تستطيع فإذا استطاعت حجت ولا يحج عنها أحد وهي مستطيعة ببدنها، أما إن كانت عجوز كبيرة يشق عليها ولم تحج فلا بأس أن يحج عنها أحد أقربائها أو غيرهم لا حرج في ذلك وينفعها، نعم.\nالمقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8377/حكم-الحج-عمن-عجز-عنه-بدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27805.mp3","categories":["النيابة في الحج"]},{"id":10432,"question":"من العراق محافظة نينوى -حي العامل- المستمعة نجمة عبدالله محمد بعثت برسالة ضمنتها جمعًا من الأسئلة، من بينها سؤال تقول فيه: لي ولد متوفى وأريد أن أحج له وقمت بتوفير راتبه أجرة لمصاريف الحج، علمًا بأن زوجي قد حج لنفسه السنة الماضية، هل يجوز لزوجي الذي قد حج لنفسه أن يحج لولدي؟","title":"حكم حج زوج المرأة عن ولدها المتوفى","answer":"","link":"https://binbaz.org.sa/fatwas/8605/حكم-حج-زوج-المراة-عن-ولدها-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34108.mp3","categories":["النيابة في الحج"]},{"id":10480,"question":"السائلة أم علي من عفيف بعثت برسالة وضمنتها سؤالين: في سؤالها الأول تقول: هل يجوز للمرأة أن تحج أو تعتمر عن والدها المتوفى، علماً بأنه ليس له من العيال أو البنات سوى أنا؟","title":"حكم قيام المرأة بالحج والعمرة عن والدها المتوفى","answer":"الجواب: نعم، للمرأة أن تحج عن والدها وعن جدها وعن أمها وعن جدتها وعن أقاربها تطوعاً منها، إذا كانوا أمواتًا أو كانوا عاجزين كبار السن لا يستطيعون الحج، فهي مأجورة في ذلك، وقد سئل النبي عن هذا عليه الصلاة والسلام فأجاب بأنه لا بأس، قالت امرأة: يا رسو ل الله! إن أبي شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال: حجي عن أبيك، وقال له رجل: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ فقال ﷺ: حج عن أبيك واعتمر، وسئل قالت له امرأة: يا رسول الله! إن أمي نذرت أن تحج فلم تحج حتى ماتت أفأحج عنها؟ قال: حجي عنها.\nوالأحاديث في هذا المعنى كثيرة، فإذا حجت المرأة عن أبيها أو أمها أو جدها أو جدتها أو إخوتها كل ذلك طيب، أو أدت عنهم ديون عليهم، أو تصدقت عنهم، أو دعت لهم كل هذا مطلوب، كله طيب.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8655/حكم-قيام-المراة-بالحج-والعمرة-عن-والدها-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28107.mp3","categories":["النيابة في الحج"]},{"id":10695,"question":"المستمع (ب. أ. م) سوادني مقيم في الرياض، بعث برسالة يقول فيها: لي والد ووالدة لم يحجا فرضهما حتى الآن، وأنا لدي النية بأن أحججهما، ولكن المشكلة أنهما كبيران لدرجة أنهما لا يتحملان مجرد السفر، فضلاً عن أداء شعائر الحج من طواف وسعي ورمي جمار، هل أحج عنهما، أو أوكل من يحج عنهما، أفيدوني جزاكم الله خيراً؟","title":"حكم الحج عن الوالدين العاجزين عن الحج","answer":"الجواب: يشرع لك الحج عنهما كل واحد وحده، تبدأ بالأم ثم الأب هذا هو الأفضل؛ لأن الرسول صلى الله عليه وسلم سئل، سأله أبو رزين العقيلي قال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ فقال عليه الصلاة والسلام: حج عن أبيك واعتمر فأنت تحج عنهما جزاك الله خيراً، وتبدأ بالأم؛ لأن حقها أكبر، ثم تحج عن الأب، وإذا حججت عنهما، يعني: استأجرت ثقة يحج عنهما فلا بأس، لكن إذا توليت ذلك أنت فهو أفضل، إلا إذا رأيت أن غيرك أفضل منك لعلمه وفضله، واتفقت معه على أن يحج عنهما فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8866/حكم-الحج-عن-الوالدين-العاجزين-عن-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33016.mp3","categories":["النيابة في الحج"]},{"id":10745,"question":"رسالة وصلت إلى البرنامج من الحديدة في اليمن، وهي من الأخت المستمعة: (م. أ. ن) تقول في رسالتها: لي أخت تبلغ من العمر الثامنة عشرة توفيت بمرض القلب وهي لم تتزوج ولم تحج ونويت أن أحج عنها، فهل يجوز لي ذلك، علماً بأنها كانت متهاونة في صلاتها أحياناً، وإن كان يجوز الحج عنها، فهل الذي يحج عنها أنا أم والدتي أم أخي؟ أفيدونا جزاكم الله خيرا.","title":"حكم حج المرأة عن المرأة المتوفية، والحج عمن يتهاون بالصلاة","answer":"الجواب: إذا كانت لا تصلي بعض الأحيان فلا تحجي عنها؛ لأن من ترك الصلاة كفر، وليس أهلاً لأن يحج عنه ولا يدعى له، أما إذا كانت تصلي ولكن ليست نشيطة وإلا هي تصلي كل وقت فإذا حججت عنها فأنت مشكورة ومأجورة، ويكون تطوعاً منك وإذا حجت عنها أمها أو غيرها من أقاربها فلا بأس، لكن لابد أن يكون الذي يحج عنها قد حج عن نفسه، فإذا حج عن نفسه وحج عن غيره فلا بأس يعني: من الأموات أو العاجزين كالشيخ الكبير والعجوز الكبيرة التي لا تستطيع الحج لا بأس أن يحج عنها غيرها من أقاربها ممن حج عن نفسه، فإذا كنت حججت عن نفسك وأردت التبرع لها بالحج فجزاك الله خيراً إذا كانت تصلي، أما إذا كانت تارة وتارة تارة تصلي وتارة لا تصلي فلا تحجي عنها، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالصلاة أمرها عظيم وهي عمود الإسلام من تركها أو تركها بعض الأحيان كفر نسأل الله العافية.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8921/حكم-حج-المراة-عن-المراة-المتوفية-والحج-عمن-يتهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34604.mp3","categories":["النيابة في الحج"]},{"id":10814,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من أحد المستمعين يقول: (ف. م) من لواء الحديدة باليمن، ومقيم في منطقة الأحساء بالمملكة بعث برسالة يقول فيها: والدتي كانت تصدق السحرة والكهان والمشعوذين، ولكنها كانت لا تعلم أن هذا حرام، وفيه إثم عظيم، وتوفيت وهي على جهلها بذلك، فهل يلحقها إثم، وهل يجوز لي أن أحج عنها، عسى الله أن يغفر لها؟ مع العلم أنها كانت تصوم، وتصلي أفيدونا، جزاكم الله خيرًا.","title":"حكم الحج عن شخص كان يصدق السحرة والكهنة","answer":"الجواب:  إذا كانت والدتك موحدة تعبد الله وحده، ولا تتعلق بأصحاب القبور، ولا تدعوهم من دون الله، ولا تستغيث بالأولياء، والأنبياء، ولكنها قد تصدق بعض السحرة فيما يخبرون به، أو بعض الكهنة عن جهل منها، فنرجو أن إسلامها باقٍ، إذا كنت لا تعلم منها ما يوجب كفرها من دعاء الأموات، والاستغاثة بالأموات، أو أن السحرة يعلمون الغيب. أما إن كانت تصدق أن السحرة يعلمون الغيب، أو تدعو الأموات، أو تستغيث بالأموات، كـابن علوان، أو غيره فهذا كفر أكبر، لا يدعى لها، ولا يحج عنها. أما إذا كنت تعلم منها أنها لا تفعل ذلك، بل هي موحدة لا تعبد إلا الله، ولا تدعو إلا الله، ولا تعتقد أن أحد يعلم الغيب، ولكنها قد تصدق بعض أخبار المشعوذين الذين يسمون بالسحرة، أو بالكهنة جهلًا منها فلا حرج في الحج عنها، والدعاء لها، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8991/حكم-الحج-عن-شخص-كان-يصدق-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35402.mp3","categories":["النيابة في الحج"]},{"id":10820,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من أحد المستمعين يقول: (ف. م) من لواء الحديدة باليمن، ومقيم في منطقة الأحساء بالمملكة بعث برسالة يقول فيها: والدتي كانت تصدق السحرة والكهان والمشعوذين، ولكنها كانت لا تعلم أن هذا حرام، وفيه إثم عظيم، وتوفيت وهي على جهلها بذلك، فهل يلحقها إثم، وهل يجوز لي أن أحج عنها، عسى الله أن يغفر لها؟ مع العلم أنها كانت تصوم، وتصلي أفيدونا، جزاكم الله خيرًا.","title":"حكم الحج عن شخص كان يصدق السحرة والكهنة","answer":"الجواب:  إذا كانت والدتك موحدة تعبد الله وحده، ولا تتعلق بأصحاب القبور، ولا تدعوهم من دون الله، ولا تستغيث بالأولياء، والأنبياء، ولكنها قد تصدق بعض السحرة فيما يخبرون به، أو بعض الكهنة عن جهل منها، فنرجو أن إسلامها باقٍ، إذا كنت لا تعلم منها ما يوجب كفرها من دعاء الأموات، والاستغاثة بالأموات، أو أن السحرة يعلمون الغيب. أما إن كانت تصدق أن السحرة يعلمون الغيب، أو تدعو الأموات، أو تستغيث بالأموات، كـابن علوان، أو غيره فهذا كفر أكبر، لا يدعى لها، ولا يحج عنها. أما إذا كنت تعلم منها أنها لا تفعل ذلك، بل هي موحدة لا تعبد إلا الله، ولا تدعو إلا الله، ولا تعتقد أن أحد يعلم الغيب، ولكنها قد تصدق بعض أخبار المشعوذين الذين يسمون بالسحرة، أو بالكهنة جهلًا منها فلا حرج في الحج عنها، والدعاء لها، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8991/حكم-الحج-عن-شخص-كان-يصدق-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35402.mp3","categories":["النيابة في الحج"]},{"id":11062,"question":"إذا توفي متوفٍ وعمره ستة عشرة سنة، فهل يكون قد فرض عليه الحج والعمرة؟","title":"حكم الحج عمن توفي في السادسة عشرة من عمره","answer":"الجواب:  نعم، إذا بلغ خمسة عشر سنة صار مكلفًا، لكن لا حج عليه إلا مع الاستطاعة، ولو هو ابن عشرين سنة، أو ستين سنة، ليس عليه حج ولا عمرة إلا بالاستطاعة، لقول الله سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]، فإذا كان فقيرًا لا يستطيع فلا حج عليه ولو كان كبيرًا، لكنه من جنس أهل الحج إذا بلغ، لكن لا يلزمه الحج إلا إذا استطاع ولا العمرة، ... كان عندهم مال يستطيعون وإلا فلا حج عليهم حتى يستطيعوا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9239/حكم-الحج-عمن-توفي-في-السادسة-عشرة-من-عمره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36712.mp3","categories":["النيابة في الحج"]},{"id":11304,"question":"يقول: هل يجوز لي تأدية فريضة الحج عن والدي المتوفى -رحمه الله- وما الواجب علي أن أفعله في تأدية الفريضة حتى تصح حجة والدي وتقبل عند الله بمشيئته تعالى؟","title":"حكم من حج عن أبيه وبيان كيفية حجه عنه","answer":"الجواب: تحج عن والدك مثلما تحج عن نفسك، تحج عن والدك مثل حجك عن نفسك، والأفضل تمتع، تأتي بعمرة من الميقات ميقات بلدك إن كنت من أهل نجد من السيل، تطوف تسعى وتقصر هذه عمرة، ثم يوم الثامن تلبي بالحج، وتذهب مع الناس إلى منى وإلى عرفات ثم مزدلفة ثم ترمي الجمار بعد يوم العيد والأيام الأخرى بالنية عن أبيك، ثم تطوف وتسعى، تطوف وتسعى لحجك، وعند الخروج تطوف للوداع سبعة أشواط بالبيت، هذا هو العمل يكون لأبيك. وإن حجيت حجًا مفردًا لبيت بحج فقط أو بحج وعمرة جميعًا، وقدمت مكة بذلك وبقيت على إحرامك ما تحللت، طفت وسعيت وبقيت محرمًا حتى ذهبت إلى منى وعرفات فيبقى عليك الطواف فقط الطواف والسعي الأول يكفي، الطواف الأول إن أتيت به عند القدوم مع السعي هذا كافٍ في مسألة السعي، ولكن تأتي بالطواف بعد الحج، يوم العيد أو بعده طواف الإفاضة للحج، ثم طواف الوداع عند الخروج، وليس عليك شيء إلا إذا كنت لبيت بالعمرة والحج قارنًا فإنك تفدي عليك فدية ذبيحة تذبح في منى أو في مكة المكرمة لهذه النية تأكل منها وتطعم، تأكل منها وتطعم الفقراء، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9474/حكم-من-حج-عن-ابيه-وبيان-كيفية-حجه-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37606.mp3","categories":["النيابة في الحج"]},{"id":11456,"question":"المستمع صلاح عبدالحميد مصطفى يسأل ويقول: سمعت من بعض الناس أن العمرة لا تجوز لمن هو متوفى، فهل ما قيل صحيح؟","title":"حكم العمرة عن المتوفى","answer":"الجواب:  ليس بصحيح إذا كان المتوفى مسلمًا؛ فإن العمرة مشروعة له، وكذلك الحج إذا اعتمرت عن أخيك الميت، أو أبيك، أو حججت عنه؛ فأنت مأجور -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9637/حكم-العمرة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38111.mp3","categories":["النيابة في الحج"]},{"id":11553,"question":"المستمع هزاع عبدالله الشرف بعث يسأل ويقول: لقد توفيت أم والدي قبل عامين وكانت تاركة للصلاة، لكنها تصوم رمضان، وقد قام والدي العام الماضي وحج لها، فهل هذه الحجة صحيحة؟","title":"حكم الحج عمن مات وهو تارك للصلاة","answer":"الجواب:  التارك للصلاة كافر عند جمع من أهل العلم، ولو كان لا يعلم منه جحود وجوبها؛ لأن ترك الصلاة من الكبائر العظيمة، وقد بين النبي ﷺ أن تاركها يكون كافرًا، يقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة والحكم يعم الرجل والمرأة، الأحكام المعلقة بالرجال تعم النساء، والمعلقة بالنساء تعم الرجال، إلا ما خصه الدليل، ولهذا في الحديث الآخر يقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وهذا يعم الرجال والنساء. ........ لا يحج عنه، ولا يعتمر عنه، لكن ذهب جمع من أهل العلم إلى أن من تركها ليس عن جحد لوجوبها، بل عن تكاسل؛ لا يكفر بذلك، ولكن أتى ذنبًا عظيمًا، ومنكرًا عظيمًا، لكن لا يكون كافرًا كفرًا أكبر، بل يكون كفره كفرًا أصغر، فعلى هذا القول: يصح الحج عنه عند جمع من أهل العلم الذين قالوا: إن المسلم لا يكفر بترك الصلاة إلا إذا جحد وجوبها. أما إذا تركها تكاسلًا وهو يعلم أنها واجبة، وأنها فريضة، ولكن حمله الكسل والتساهل على الترك؛ فهذا عند جمع من أهل العلم لا يكفر بذلك كفرًا أكبر، بل يكون كفرًا أصغر. والصواب والأظهر في الدليل أنه يكون كافرًا كفرًا أكبر -والعياذ بالله- لأن الصلاة عمود الإسلام، من حفظها؛ حفظ دينه، ومن ضيعها؛ فقد ضيع دينه، نسأل الله العافية. وبذلك يعلم أن من كان تاركًا للصلاة لا يحج عنه، ولا يدعى له- نسأل الله العافية- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9736/حكم-الحج-عمن-مات-وهو-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29702.mp3","categories":["النيابة في الحج","حكم الصلاة وأهميتها"]},{"id":11556,"question":"أم أيمن بعثت تسأل وتقول: إذا كان الإنسان لم يحج فريضة الحج، فهل يجوز له أن يحج عن شخص له متوفى، بمعنى: أن يعطي مبلغًا من المال لأحد الأشخاص ليؤدي فريضة الحج لذلك المتوفى؟ وهل من شروط الحج؟ ويجب أن تكون فيمن سيقوم بالحج؟ سؤال مشوش بعض الشيء.","title":"حكم بذل من لم يحج عن نفسه المال للحج عن قريبه","answer":"الجواب: لا حرج أن يحجج الإنسان عن غيره بمال يبذله، وإن كان ما بعد حج، فإذا دفع الإنسان مالًا لبعض الثقات يحج عن أبيه أو عن أمه، أو عن زوجته أو أخيه أو نحو ذلك؛ فلا بأس، ولو كان ما حج عن نفسه؛ فالممنوع أن يحج بنفسه عن غيره، لا يحج إلا حتى يحج، لا يحج عن غيره حتى يحج بنفسه، إذا كان حاجًا بنفسه، لا يحج عن غيره إلا إذا حج عن نفسه. أما إذا استعان بغيره، ودفع مالًا لغيره، ليحج عن أبيه أو أمه أو أخيه، أو غير ذلك؛ فلا حرج في ذلك؛ لأن الحاج غيره ليس هو الحاج هو، وإنما هو قد بذل ماله في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9739/حكم-بذل-من-لم-يحج-عن-نفسه-المال-للحج-عن-قريبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29705.mp3","categories":["النيابة في الحج"]},{"id":11679,"question":"قضية مماثلة لقضية سبقت، وصاحبها في هذه المرة هو السيد محمد أبو شنب من جمهورية مصر العربية، ومقيم في القصيم للعمل كما يقول: قضيته تتلخص في أن زوجته كانت مريضة جدًا، ولم تستطع أن تطوف طواف الإفاضة والوداع معًا، وحينئذٍ وكلته ليطوف عنها وطاف، هل يصح ذلكم العمل شيخ عبدالعزيز؟","title":"حكم توكيل المريض لغيره في طواف الإفاضة والوداع","answer":"الجواب:  لا، عليها أن ترجع لا يصح التوكيل في هذا، لا في طواف الإفاضة، ولا في طواف الوداع، بل يطاف بها محمولة إذا كانت تعجز عن المشي، تطوف في العربانة .. أو على رؤوس الرجال، ولا توكل، نعم، فعليها أن ترجع من القصيم، وتطوف طواف الإفاضة، ويكفيها عن الوداع، إلا إذا جلست بعد طواف الإفاضة وقتًا طويلًا فإنها تطوف للوداع أيضًا، أما إذا طافت طواف الإفاضة، وخرجت؛ كفاها عن طواف الوداع. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9860/حكم-توكيل-المريض-لغيره-في-طواف-الافاضة-والوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39009.mp3","categories":["النيابة في الحج"]},{"id":11783,"question":"أول أسئلة هذه الحلقة سؤال يقول: سماحة الشيخ! قمت بالحج في العام الماضي مع الوالدة، وأخ لي وفي يوم العيد نزلنا إلى منى مبكرين، وعندما وصلنا إلى منى طلب مني أخي أن أبقى مع الوالدة، وأخبرني بأنه سوف يرمي نيابة عني، وأنه ليس لازمًا الرمي بنفسي، مع أن الزحام لم يكن شديدًا، وكذلك في اليوم الثاني لم أرم، وإنما رمى هو نيابة عني حيث كان الزحام شديدًا، فهل يجوز لي ذلك أم لا؟ وإذا كان لا يجوز فماذا أفعل؟ وجزاكم الله خيرًا، وهذا السؤال من الأخت (ج. أ. س).","title":"حكم التوكيل في الرمي للحاج المستطيع","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد: فإذا كان الواقع هو، ما ذكرته السائلة، وأنه رمى عنها أخوها بلا عذر، وهي مستطيعة، ليس بها مانع، فإن عليك أيها الأخت في الله دمًا يذبح في مكة للفقراء عن ترك الرمي، وأنت قادرة، نسأل الله للجميع التوفيق والقبول. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم، إذا كان أخوها أبقاها مع والدتها؛ لأنسها، ولقضاء حوائجها. الشيخ: ليس بعذر، ليس بعذر، عليها دم يذبح بمكة كالضحية شاة، رأس من الغنم كالضحية تذبح بمكة للفقراء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9963/حكم-التوكيل-في-الرمي-للحاج-المستطيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39501.mp3","categories":["النيابة في الحج"]},{"id":11792,"question":"يقول: عندي والدة بها مس من الجن، ولا تستطيع الجلوس في الزحام، ولا تطيق الزحام، ولم تحج حتى الآن، فهل لي أن أحج عنها، أو لأبي، علمًا بأن الوالد قد حج -ولله الحمد- أفتونا جزاكم الله خيرًا؟","title":"حكم الحج عمن به مس من الجن","answer":"الجواب:  مثل هذه يرجى أن تشفى، وأن تعافى، وعليكم أن تجتهدوا في القراءة عليها؛ لعل الله يشفيها من هذا المس، تقرأ عليها أنت، أو أبوك، يقرأ عليها أخوك، يقرأ عليها من هو معروف بالخير؛ لعل الله أن يزيل عنها هذا البلاء، والمعروف أن المجنون إذا قرئ عليه الآيات القرآنية، أو الدعوات الطيبة، ونوشد هذا الجني بالله، وحذر من الظلم، أن الله  يخرجه منها، فعليكم أن تجتهدوا في الأسباب؛ لعل الله سبحانه يشفيها من هذا البلاء، وتحج بنفسها، والحمد لله، نعم. المقدم: الحمد لله. إذًا لا يتعجلون الآن؟ الشيخ: لا يتعجلوا؛ لأنه يرجى برؤه، يرجى زواله، ما هو بميؤوس منه، نعم. المقدم: إذًا عليهم أن يبذلوا الأسباب؟ الشيخ: عليهم أن يبذلوا الأسباب، نعم. المقدم: بارك الله فيكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9976/حكم-الحج-عمن-به-مس-من-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42209.mp3","categories":["النيابة في الحج"]},{"id":11852,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الجمهورية التونسية، وباعثها أخ لنا من هناك يقول أخوكم في الله يوسف مفتاح، الأخ يوسف عرضنا له سؤال في حلقة مضت وفي هذه الحلقة يسأل سماحتكم ويقول: جدي شيخ مسن لا يقدر على الحركة وهو يملك مالًا كثيرًا، والحمد لله، ولم يكتب له الحج إلى بيت الله الحرام، فهل تكتب له الحجة إذا مكن إنسانًا فقيرًا من الحج من أمواله الخاصة؟ جزاكم الله خيرًا.","title":"حكم من لم يستطع الحج لكبر سنه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. إذا كان هذا الرجل عاجزًا عن الحج لكبر سنه، لا يستطيع الحج في السيارات، ولا بالطائرات؛ فإنه يستنيب؛ يخرج من ماله بيد ثقة من الطيبين؛ حتى يحج عنه من ماله، وقد ثبت عنه ﷺ أنه سألته امرأة قالت: يا رسول الله! إن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عن أبيك وسأله أبو رزين العقيلي فقال: إن أبي شيخ كبير لا يستطيع الحج، ولا الظعن، أفأحج عنه؟ قال: حج عن أبيك واعتمر فالحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10021/حكم-من-لم-يستطع-الحج-لكبر-سنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39601.mp3","categories":["النيابة في الحج"]},{"id":11919,"question":"هل يجوز لي أن أحج عن والدتي التي تبلغ من العمر سبعين عامًا، وما زالت نشيطة؟","title":"حكم الحج عن الأم الكبيرة العاجزة","answer":"الجواب:  ليس لك أن تحج عنها إلا إذا عجزت لكبر السن، أما ما زالت نشيطة تحج لنفسها، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/10103/حكم-الحج-عن-الام-الكبيرة-العاجزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42620.mp3","categories":["النيابة في الحج"]},{"id":12012,"question":"يقول: هل يجوز الطواف، أو العمرة عن الوالدين؟ وكم تكون الهرولة في الطواف والسعي؟","title":"حكم الطواف والعمرة عن الوالدين","answer":"الجواب:  إذا كان الوالدان ميتين، أو عاجزين لكبر السن، أو مرض لا يرجى برؤه؛ فلا بأس أن تعتمر عنهما، وأن تحج عنهما كل واحد على حدة، لمجيء الأحاديث في ذلك عن النبي -عليه الصلاة والسلام- فإنه سئل كثيرًا عمن قال: توفي أبي وعليه كذا، توفيت أمي وعليها حجة، فقال: حج عن أبيك حج عن أمك وسمع رجلًا يقول: لبيك عن شبرمة قال: من شبرمة؟ قال: أخ لي، أو قريب لي، قال: حججت عن نفسك؟ قال: لا، قال: حج عن نفسك ثم حج عن شبرمة فدل ذلك على أنه لا حرج في الحج عن الغير إذا كان ميتًا، أو عاجزًا لمرض لا يرجى برؤه، أو لكبر السن. أما الطواف لا، لا يشرع، الطواف عن الحي أو الميت ليس عليه دليل، والعبادات توقيفية لا تفعل إلا بالدليل، ولا نعلم دليلًا يدل على التقرب بالطواف وحده، بل تطوف عن نفسك فقط، كما تصلي عن نفسك، أما الحج والعمرة؛ فلا بأس أن تحج عن غيرك، وأن تعتمر عن غيرك إذا كان ميتًا، أو عاجزًا لكبر، أو مرض لا يرجى برؤه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10197/حكم-الطواف-والعمرة-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43203.mp3","categories":["النيابة في الحج"]},{"id":12086,"question":"هل يجوز أن أحج عن والدتي؟ علمًا بأنني قد حجيت عن نفسي ووالدتي متوفاة.","title":"حكم الحج عن الوالدة المتوفاة","answer":"الجواب:  يستحب لك أن تحج عنها، وتعتمر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10271/حكم-الحج-عن-الوالدة-المتوفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43520.mp3","categories":["النيابة في الحج"]},{"id":12136,"question":"هل يجوز لي عند تأدية مناسك العمرة أن أعتمر لوالدي ولوالدتي في نفس الوقت؟","title":"حكم تأدية العمرة عن الوالدين في وقت واحد","answer":"الجواب:  لا حرج في ذلك إذا اعتمر المسلم لنفسه، وأحب أن يعتمر لأبيه وأمه؛ فلا بأس؛ إذا كانا ميتين، أو كانا عاجزين لكبر سنهما، أو لمرضهما الذي لا يرجى برؤه، فلا بأس أن يعتمر عنهم، بل يشرع ذلك، بل من برهما العمرة عنهما، والحج عنهما. فإذا فرغ من عمرته، خرج للتنعيم، أو للجعرانة أو لعرفات، يعني: الحل خارج الحرم، فيحرم من هناك، ثم يطوف ويسعى ويقصر بالنية عن أمه، أو عن أبيه، أو عن غيرهما من الأموات، أو العاجزين عجزًا لا يستطيعون معه الحج والعمرة؛ لكبر سنهما، لكبر السن، أو لمرض لا يرجى برؤه، ليس خاصًا بالأبوين، بل لو اعتمر عن أخيه أو ابنه أو خاله أو عمه أو أخيه أو صديقه المسلم؛ لا بأس، إذا كان ميتًا أو عاجزًا عجزًا يمنعه من الحج والعمرة؛ لكبر السن، أو للمرض الذي لا يرجى برؤه.  والنبي ﷺ أمر عائشة من التنعيم لما كانت في مكة، أخرجها للتنعيم واعتمرت فدل ذلك على أن الذي في مكة إذا أراد العمرة يكفيه الخروج إلى التنعيم، أو غيره من الحل، يحرم من هناك، ويلبي بالعمرة من هناك، ويكفي، أما الحاج لا، من نفس مكة، الحج يحرم من نفس مكة، ولا يحتاج إلى الخروج، نعم، إذا كان من أهل مكة، أو مقيم بها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10321/حكم-تادية-العمرة-عن-الوالدين-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43905.mp3","categories":["النيابة في الحج"]},{"id":12338,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها مستمع يقول: أخوكم في الله هايل مسحم محمد أبو المهدي يقول: بالنسبة إلى العمرة لقد وفقني الله وبعض الإخوة لزيارة مكة المكرمة من أجل أداء مناسك العمرة، وحيث إنني أديت العمرة عن نفسي، وثلاث عمرات أخرى أوهبتها للوالدين، وزوجتي بالترتيب، وكنت في كل عمرة أتحلل، وأذهب للتنعيم للإحرام بالأخرى، وحيث أن هذا العمل كان موضع جدال بيني وبين الإخوة من ناحية جوازه، الرجاء الإفادة عن هذا العمل، وعن طريقته وحكمه، وجوازه؟ جزاكم الله خيرًا.","title":"حكم تكرار العمرة، وإهداء ثوابها للغير","answer":"الجواب:  الصواب: أنه لا بأس بذلك، لقول النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة متفق على صحته، ولم يحدد مدة بين العمرتين، لكن إذا كان المقام فيه مضايقة للحجاج، وفيه أذى وزحمة؛ فالأولى ترك ذلك إلى وقت السعة، أما إذا كان الوقت فيه سعة، وليس فيه إيذاء لأحد؛ فلا حرج في ذلك -إن شاء الله-إذا كان المعتمر عنهم ميتين، أو عاجزين، لا يستطيعون على العمرة، ولا الحج لكبر السن، أو مرض لا يرجى برؤه، نعم. المقدم: جزاكم الله خيرًا، وإذا كانوا أقوياء سماحة الشيخ؟ الشيخ: لا لا يعتمر عنهم، ولا يحج عنهم، ... أقوياء .. لا يحج عنهم، ولا يعتمر عنهم، وإنما الحج والعمرة عن إنسان كبير السن، لا يستطيع الحج، أو مريض لا يرجى برؤه. المقدم: بارك الله فيكم، من فعل ذلك سماحة الشيخ؟ الشيخ: في الحج لا، من فعل الحج عمن لا يستحق، من فعل حجًا أو عمرة عمن لا تجزئ عنه؛ صار له، صارت حجته له. المقدم: ما شاء الله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10544/حكم-تكرار-العمرة-واهداء-ثوابها-للغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39903.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":12435,"question":"بعد هذا ننتقل إلى رسالة بعث بها المستمع حسين عبدالله محمد أحمد، الأخ حسين يقول: أنه معوق، ولديه ثلاث بنات، يسأل: هل يجب علي أن أعتمر لأبي وأمي؟ وبأيهما أبدأ؟ جزاكم الله خيرًا.","title":"حكم الحج والعمرة عن الوالدين وبأيهما يبدأ","answer":"الجواب:  إذا كانا ميتين، ولم يحجا، ولم يعتمرا؛ شرع لك أن تعتمر لهما، وتحج لهما، وتبدأ بالأم، الأم أحق، أما إذا كانا قد اعتمرا وحجا؛ فالأمر واسع، والحمد لله، إن اعتمرت عنهما؛ فلا بأس، وإلا فالأمر واسع. وهكذا الحج إذا كانا لم يحجا، ولم يعتمرا؛ فإنك تحج عنهما وتعتمر عنهما على سبيل الأفضلية، سنة ليس بواجب عليك إلا إذا كان خلفهما مال، فإنه يجب عليك أن تحجج من مالهما إذا كان ماتا وهما يقدران، ماتا وهما يقدران على الحج، لكن تساهلا، فإن الحجة تخرج من مالهما، أو تحج أنت من مالك ويكفي، وتعتمر من مالك ويكفي، والحمد لله. أما إذا كانا فقيرين حين ماتا؛ لم تجب عليهما الحج والعمرة، فأنت يشرع لك أن تحج عنهما من باب برهما، وتعتمر عنهما من باب برهما، وتبدأ بالأم؛ لأنها أحق، ثم الحج عن الوالد، أما البنات فلا يجب عليهن حج إلا إذا كن يقدرن على الحج من مالهن، فإذا قدرن؛ وجب عليهن الحج، وعلى محرمهن أن يكون معهن في الحج، يحتسب الأجر، كأخيهن، أو عمهن، أو تحج بهن أنت، يشرع لك أن تحج بهن، أو يحج بهن أخوهن، أو بعض أعمامهن، أو أخوالهن من باب الأجر لا يجب، لكن يشرع له أن يحتسب الأجر، وأن يحج معهن حتى يؤدين فرض الحج والعمرة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10649/حكم-الحج-والعمرة-عن-الوالدين-وبايهما-يبدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40314.mp3","categories":["النيابة في الحج"]},{"id":12599,"question":"المستمع (علي . م. ف) من القنفدة بعث برسالة يقول فيها: لوالدتي أخوان: أحدهما قد حج، والثاني لم يحج، وكلاهما قد توفي إلى رحمة الله، في العام الماضي أعطتني والدتي مبلغًا من المال، وطلبت مني أن أبحث عن شخص يحج عن أخيها الذي لم يحج، فوجدت الشخص المطلوب، واتفقت معه، ولكنه عندما طلب مني اسم الشخص الذي سيحج عنه ذكرت له اسم الذي قد حج؛ لأني لا أعرفه، وعندما أخبرت والدتي قالت لي: إنني قد أعطيته اسم أخيه، وقد تم الحج على هذا الأساس، فهل تكون الحجة للذي نوته والدتي، أم للذي تلفظت باسمه؟ وهل يلزمنا الحج عنه؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الخطأ في اسم من حج عنه","answer":"الجواب:  الحج يكون لمن نوته الوالدة، أما الغلط في الأسماء ما يضر، ولا يؤثر، الحج للشخص الذي لم يحج، وهو الذي نوت الوالدة أن يكون الحج عنه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10808/حكم-الخطا-في-اسم-من-حج-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41311.mp3","categories":["النيابة في الحج"]},{"id":12769,"question":"المستمع محمد ناجي محبوب من مكة المكرمة بعث برسالة، وضمنها جمعًا من الأسئلة، في أحدها يقول: قمت في العام الماضي بفريضة الحج عن نفسي، ثم في السنة التالية قمت في رمضان بعمرة عن جدتي، وفي نفس السنة قمت بالحج عنها أيضًا، ولم آت بعمرة لها بعد نهاية الحج، فهل ما قمت به صحيحًا في الحج عنها؟","title":"حكم العمرة عن الجدة ثم الحج عنها في نفس السنة","answer":"الجواب:  كله طيب، جزاك الله خيرًا، هذا من البر والصلة، وجزاك الله خيرًا، فالعمرة حسنة في رمضان، والحج كذلك، ولا حاجة إلى عمرة بعد رمضان، ولا بعد الحج، فالعمرة في رمضان عنها كافية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10983/حكم-العمرة-عن-الجدة-ثم-الحج-عنها-في-نفس-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41918.mp3","categories":["النيابة في الحج"]},{"id":12770,"question":"هل يجوز أن أقوم بالطواف حول الكعبة لوالدتي؟","title":"حكم الطواف حول الكعبة عن الغير","answer":"الجواب:  ليس عليه دليل، تركه أولى، تطوف عن نفسك، وتدعو لها في طوافك، قد تدعو لغيرها من أقاربك من المسلمين؛ لأني لا أعلم في هذا شيئًا صحيحًا عن النبي ﷺ يدل على أن يطاف عن الغير، وإنما يحج عن الغير أو يعتمر، حجًا كاملًا، أو عمرة كاملة، أما أن يطوف عن فلان، أو فلان فليس عليه دليل فيما أعلم، وإنما يطوف لنفسه، ويدعو لمن أحب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10984/حكم-الطواف-حول-الكعبة-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41919.mp3","categories":["النيابة في الحج"]},{"id":12848,"question":"هل يجوز أن آتي بعمرتين لوالدتي ووالدي في وقت واحد؟","title":"حكم تأدية العمرة عن الوالد والوالدة في وقت واحد","answer":"الجواب:  نعم، لا حرج في ذلك، كل واحد له عمرة خاصة، كل واحد له عمرة وإحرام خاص، تحرم بالعمرة لأبيك، أو لأمك، ثم تكرر لأبيك أو لأمك.. لا حرج في ذلك، والحمد لله؛ لأن النبي  قال: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة، ولم يحدد بين العمرتين، أيامًا معدودة؛ فدل على الجواز، والحمد لله.  وقد اعتمرت عائشة -رضي الله عنها- في أقل من عشرين يومًا عمرتين -رضي الله عنها- في حجة الوداع، عمرة مع حجها، وعمرة مفردة في ليلة أربع عشرة من ذي الحجة بأمر النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، إذًا يطوف مرتين والحالة هذه، ويسعى مرتين، ويحرم مرة واحدة؟ الشيخ: لا، يحرم مرتين، ويسعى مرتين، ويطوف مرتين، كل واحدة لها إحرام خاص، يحرم لأبيه، أو أمه مثلًا، فإذا فرغ منها، وأحب أن يحرم لأبيه بعد يوم، أو يومين، أو أكثر، أو أقل؛ لا بأس، لكن الإحرام يكون لواحد فقط. المقدم: الإحرام واحد؟ الشيخ: .... ثم يكون الإحرام لواحد منهما، ثم يحرم إحرامًا ثانيًا للثاني، ما يكون الإحرام عن اثنين أبدًا، ما يكون إلا عن واحد، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11063/حكم-تادية-العمرة-عن-الوالد-والوالدة-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46414.mp3","categories":["النيابة في الحج"]},{"id":13045,"question":"السائل: التي رمزت لاسمها بـ (ق. م. ع) مكة المكرمة، تقول: بأنها مصرية، ومقيمة بمكة المكرمة، وحجت حجة الفريضة عن نفسها، وتريد أن تحج هذا العام عن والدها، تقول: هل يجوز لي أن أحج عنه علمًا بأنه على قيد الحياة، ومريض، ولا يستطيع أن يحج بسبب المشقة، ووالدي بلغ سن الشيخوخة، ولا يستطيع الحركة، فأفيدوني بذلك يا سماحة الشيخ؟","title":"حكم حج المرأة عن أبيها","answer":"الجواب: طيب لا بأس مأجورة -إن شاء الله- إذا حججت عن أبيك العاجز عن الحج، أنت مأجورة والحمد لله، قد أديت الحج عن نفسك، والحمد لله، فإذا حججت عن أبيك، أو أمك الميت، أو العاجز؛ فلا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/11262/حكم-حج-المراة-عن-ابيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50505.mp3","categories":["النيابة في الحج"]},{"id":13277,"question":"أحد الإخوة المستمعين بعث برسالة يقول فيها: هل الأولى أن أحجج والدي، أم أفتح مدرسة لمكافحة الأمية -جزاكم الله خيرًا- وصاحب هذا السؤال مقيم في المنطقة الشمالية، وهو: بلال رباح ؟","title":"هل الأولى تحجيج الوالدين أم فتح مدرسة لمكافحة الأمية؟","answer":"الجواب:  إذا كان والدك عاجزًا عن الحج لكبر سنه، أو لمرض لا يرجى برؤه؛ تحج عنه، وهذا من بره وفضله عظيم، أو أراد منك أن تحججه؛ لأنه يستطيع الحج ولكن ما عنده مال، وأراد منك أن تحججه؛ فأنت أيضًا ينبغي لك أن تحججه هذا من بره، فيتأكد عليك أن تجيب دعوته إذا كنت قادرًا، وتحتسب في ذلك. أما تفضيل ذلك على فتح مدرسة للقرآن، فهذا محل نظر، ولعلك تستطيع هذا وهذا، تقوم بالواجب، تقوم بما شرع الله من بره بالحج عنه، أو بتحجيجه بنفسه إن كان يستطيع، مع فتح المدرسة، إذا تيسر ذلك في المسجد، أو في بناء خاص. والأقرب عندي في مثل هذا أنك تبدأ بأبيك إذا كان عاجزًا، أو قادرًا، يطلب منك أن تلبي رغبته؛ لأن حجه بر عظيم به؛ ولأن له في ذلك مصلحة عظيمة، وفائدة كبيرة، فإذا قدمته، ثم بعد ذلك تسعى في الدار التي تريدها، جمعت بين الخيرين، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11563/هل-الاولى-تحجيج-الوالدين-ام-فتح-مدرسة-لمكافحة-الامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47608.mp3","categories":["النيابة في الحج"]},{"id":13369,"question":"هذا السائل (م. محمد محمدي ) مقيم بالمدينة المنورة، يقول: رجل يملك من المال ما يمكنه من الحج بنفسه من هناك، ولكنه يريد أن ينوب عنه رجل آخر يسكن في السعودية؛ وذلك لأن الرجل المذكور يحس بخطر على نفسه في خروجه من بيته، فهل يجوز له ذلك؟","title":"حكم استنابة القادر غيره في الحج خوفاً على نفسه","answer":"الجواب: لا، ليس له أن يستنيب، بل يصبر حتى يستطيع، ويحج بنفسه، إلا العاجز الهرم، والمريض الذي لا يرجى برؤه، له أن يستنيب، أما ما دام قويًا، ولكن عنده تخوف من الخروج؛ يصبر حتى يزول الخوف، لا يعجل، أو ينتقل من بلد إلى بلد يأمن فيها، يترك البلد التي فيها الخوف، ينتقل حتى يتمكن من الحج، مثل المريض بمرض خفيف، لا يعجل، ليس عليه الخروج حتى يطيب من مرضه، ومثل الإنسان الذي عنده مشاغل شغلته عن الحج؛ فأجله إلى الحج الثاني مشاغل، لا حيلة فيها. المقصود: أن مثل هذا لا يعجل، ولا يستنيب حتى يزول الخوف، وينتقل إلى بلد أخرى، أو يحج من بلده التي فيها الخوف، ويسلم، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11656/حكم-استنابة-القادر-غيره-في-الحج-خوفا-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52410.mp3","categories":["النيابة في الحج"]},{"id":13650,"question":"السائل محمد (أ. أ.) يقول: أديت العمرة، وبعد خلعي ملابس الإحرام أحرمت بالعمرة لوالدي، ما حكم عملي ووالدي حي يرزق؟","title":"حكم العمرة عن الغير","answer":"الجواب: إذا كان والدك يستطيع أن يعتمر لا تعتمر عنه، تكون العمرة لك ثانية، أما إذا كان عاجزًا هرمًا لا يستطيع العمرة، أو ميتًا؛ فلا بأس. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11986/حكم-العمرة-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52821.mp3","categories":["النيابة في الحج"]},{"id":13702,"question":"من أسئلته يقول: هل يجوز أن أقوم بتوكيل شخص ما لكي يؤدي فريضة الحج عن والدي المتوفى؟ وما شرط ذلك في الوكالة؟","title":"حكم توكيل شخص بالحج عن المتوفى","answer":"الجواب: لا حرج في ذلك أن تعطيه من مالك ما يحج به عن والدك المتوفى، لا حرج في ذلك، إذا كان أهلًا لذلك، إن كان مسلمًا أهلًا لذلك، تختار الرجل الطيب الذي ترجو أن الله يتقبل منه؛ فلا بأس، ترجو الرجل الطيب المعروف بالخير، وتستنيبه في الحج عن والدك الميت، أو أمك الميتة، أو تحج أنت عنهما. نعم. وهكذا الشيخ الهرم العاجز كالميت والعجوز الهرمة التي ما تستطيع الحج كالميت؛ لقوله ﷺ لما سأله أبو رزين العقيلي، قال: «يا رسول الله! إن أبي شيخ كبير لا يثبت على الراحلة، أفأحج عنه وأعتمر؟ قال: حج عن أبيك واعتمر وقالت امرأة له: «يا رسول الله! إن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عن أبيك ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12080/حكم-توكيل-شخص-بالحج-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53508.mp3","categories":["النيابة في الحج"]},{"id":13919,"question":"السائل (م. ر) مصري ومقيم بالرياض يقول: أنا مصري ومقيم في المملكة العربية السعودية بالرياض فهل يجوز لي أن أحج عن والدتي؛ حيث أن والدتي بها مرض ولا تستطيع المشي إلا على العصا ولديها ضعف في النظر وهي في مصر وفي طول عناء، فهل يجوز أن أحج عنها؟","title":"حكم حج الابن عن أمه المريضة العاجزة","answer":"الجواب: نعم، لا بأس أن تحج عنها إذا كانت لا تستطيع الحج لضعفها ومرضها وكبر سنها فقد جاء للنبي ﷺ امرأة، فقالت: يا رسول الله! إن أبي شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال:  حجي عنه وجاءه رجل فقال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ فقال ﷺ: حج عن أبيك واعتمر فإذا كانت عاجزة فأنت جزاك الله خير تحج عنها، وتعتمر عنها لكبر سنها وعجزها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12319/حكم-حج-الابن-عن-امه-المريضة-العاجزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54409.mp3","categories":["النيابة في الحج"]},{"id":13927,"question":"السائل (م. ر) مصري ومقيم بالرياض يقول: أنا مصري ومقيم في المملكة العربية السعودية بالرياض فهل يجوز لي أن أحج عن والدتي؛ حيث أن والدتي بها مرض ولا تستطيع المشي إلا على العصا ولديها ضعف في النظر وهي في مصر وفي طول عناء، فهل يجوز أن أحج عنها؟","title":"حكم حج الابن عن أمه المريضة العاجزة","answer":"الجواب: نعم، لا بأس أن تحج عنها إذا كانت لا تستطيع الحج لضعفها ومرضها وكبر سنها فقد جاء للنبي ﷺ امرأة، فقالت: يا رسول الله! إن أبي شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال:  حجي عنه وجاءه رجل فقال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ فقال ﷺ: حج عن أبيك واعتمر فإذا كانت عاجزة فأنت جزاك الله خير تحج عنها، وتعتمر عنها لكبر سنها وعجزها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12319/حكم-حج-الابن-عن-امه-المريضة-العاجزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54409.mp3","categories":["النيابة في الحج"]},{"id":14192,"question":"من سوريا سائل للبرنامج يقول عامل في السعودية سؤالي: لي عم عاجز عن الحج فهل يحق لي الحج عنه؟ هو لم يستطيع المشي، وقد أنابني في الحج عنه فهل يجوز ذلك؟","title":"هل يجوز الحج عن العاجز؟","answer":"الجواب: إذا كان عاجزًا لا بأس، «جاءت امرأة فقالت: يا رسول الله! إن أبي شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال: حجي عن أبيك، «وجاءه رجل فقال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ قال: حج عن أبيك واعتمر.\nفإذا كان عمك عاجزًا لا يستطيع الحج لكبر سنه أو مرض لا يرجى برؤه فلك الحج عنه، وأنت مأجورة. نعم.","link":"https://binbaz.org.sa/fatwas/12645/هل-يجوز-الحج-عن-العاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54724.mp3","categories":["النيابة في الحج"]},{"id":14302,"question":"قبل ثماني سنوات كلفتُ أحد الأشخاص بأن يحج عن والدتي مقابل مبلغٍ معينٍ دفعته له كاملًا، ثم سمعت أخبارًا من بعض الناس مفادها: أن معظم الذين يحجون مقابل بعض المال يأخذون في الحجة الواحدة من أكثر من شخصٍ، فلو صحَّ هذا هل الحجة التي نويتها لوالدتي صحيحةٌ؟ أم هل يلزمني أن أحج عنها مرةً ثانيةً؟أفيدوني جزاكم الله خير الجزاء.","title":"توجيه لمَن أناب شخصًا بالحج ثم شكَّ في حجه","answer":"الجواب: إذا كان الذي دفعت له المال ثقةً عندك مأمونًا فلا يضرك ما تسمع من الكلام، فالأصل أنه أدَّى ما عليه وحجَّ عن أمك، هذا هو الأصل في الثقة المأمون، فإن كان عندك شكٌّ فيه وحججتَ عن أمك من جهة نفسك؛ هذا خيرٌ إلى خيرٍ، وفضلٌ إلى فضلٍ، وإن كانت لم تحج فريضتها، وقد خلَّفت مالًا؛ وجب عليك الحج عنها من مالها إذا كانت غنيةً حين ماتت ولم تحج. أما إذا كان الحج تطوعًا فالأمر في هذا واسعٌ والحمد لله، وقد فعلت عنها خيرًا بأن استنبتَ مَن يحج عنها، والأصل أنه حجَّ عنها -إن شاء الله- إذا كان ثقةً، وإن حججتَ زيادةً مرةً، أو مرتين، أو أكثر؛ فلك أجر ذلك.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12809/توجيه-لمن-اناب-شخصا-بالحج-ثم-شك-في-حجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62213.mp3","categories":["النيابة في الحج"]},{"id":14784,"question":"أسأل سماحة الشيخ حيث قمت بالحج عن جدي، ولقد أديت كل المناسك بأكملها، فهل تجوز الحجة عنه مع أنه متوفى إلى رحمة مولاه؟","title":"هل يجوز الحج عن الميت؟","answer":"الجواب: نعم إذا كنت قد حججت عن نفسك فقد أحسنت، وهذا من صلة الرحم، ومن البر، فجزاك الله خيرًا.  وأما إذا كنت ما حججت عن نفسك فإنها تقع عنك هذه الحجة، وفي إمكانك أن تحج عنه مرة أخرى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13283/هل-يجوز-الحج-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63809.mp3","categories":["النيابة في الحج"]},{"id":14854,"question":"المستمع (س. م. ح) من بلدة ذوقان، بعث برسالة يقول فيها: عندما يتوفى شخص، ويوصي شخصًا آخر بأن يحج عنه، والموصى لم يستطع أن يحج، ولم يخبر أهل المتوفى بذلك، ماذا عليه أن يفعل؟ هل يحج عنه دون أن يخبر أهل المتوفى؟ أم يخبرهم مع ما في ذلك من حرج شديد؟ أفيدونا، جزاكم الله خيرًا.","title":"حكم من أوصاه الميت بالحج عنه ولم يستطع","answer":"الجواب: إذا حج عنه بموجب الوصية من مال نفسه، من باب الإحسان جزاه الله خيرا، أما إذا كان أوصى أن يحج عنه من ماله فلا بد دخول أهل الميت؛ لأن قوله ما يكفي، لا بد من بينة شاهدين يشهدان بأنه أوصى بالحجة. المقدم: من التركة يعني؟ الشيخ: من التركة، وأما إذا أراد أن يحج عنه من ماله تبرعًا؛ لأنه أوصاه بذلك فجزاه الله خيرًا، ولا حاجة إلى أن يعلمهم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13344/حكم-من-اوصاه-الميت-بالحج-عنه-ولم-يستطع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63823.mp3","categories":["النيابة في الحج"]},{"id":14926,"question":"رسالة وصلت إلى البرنامج من: الحاجة (ق) من محافظة ميسان في العراق، تقول: إنني حاجة أنا وزوجي وابنتي مرتين، ولم نعتمر، وتوفي أبو ابنتي وكان وهو حي عازم على حج العمرة ولم يعتمر، هل يجوز أن أعتمر له أنا وابنتي؟ ونحن لم نعتمر لأنفسنا؟ ابنتي حجت مرتين، وكانت لم تبلغ سن الرشد، والآن بلغت سن الرشد، هل يجوز أن تعتمر لوالدها؟ أو أحد أقاربنا، أو يعتمر أحد الغرباء؟وجهونا حول هذا الموضوع. جزاكم الله خيرًا.","title":"حكم العمرة عن الغير لمن لم يعتمر عن نفسه","answer":"الجواب: على البنت الحج؛ لأنها حجت قبل أن تبلغ، فعليها الحج، حجة الفريضة بعد بلوغها، والعمرة أيضًا، وأنت كذلك عليك العمرة، وليس لكما العمرة عن الميت إلا بعد اعتماركما عن أنفسكما، وإذا تيسر من يعتمر له من الناس الذين قد اعتمروا لأنفسهم ولو بالبدل، ولو بدفع ما يساعده على ذلك؛ فلا بأس بذلك.  والعمرة واجبة مرة في العمر كالحج، فالذي لم يعتمر فيما مضى يجب عليه أن يعتمر إذا استطاع ذلك كالحج، أما العاجز؛ فليس عليه شيء لا حج، ولا عمرة، لأن الله يقول سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97]. فعلى كل مستطيع من الرجال والنساء إذا بلغ الحلم؛ أن يحج حجةً واحدة في العمر، وأن يعتمر مرةً واحدة في العمر، وإذا حج عن نفسه، واعتمر عن نفسه؛ جاز له أن يحج عن غيره من الأموات، وأن يعتمر عن غيره من الأموات، من أقاربه وغيرهم، وهكذا له الحج عن العاجز كالشيخ الكبير؛ لأنه كالميت، والعجوز الكبيرة العاجزة عن الحج لأقاربهما الحج عنهما والعمرة عنهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13427/حكم-العمرة-عن-الغير-لمن-لم-يعتمر-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64009.mp3","categories":["النيابة في الحج"]},{"id":15087,"question":"نبدأ أولًا برسالة أحمد محمود من السودان التي يقول فيها: هل يجوز أداء العمرة بدلًا من المتوفى أم أهدي ثوابها له؟ وإن كان جائزًا، أرجو ذكر النية، أو صيغة ما أقول في ذلك؟وفقكم الله.","title":"مشروعية العمرة عن الميت والعاجز","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخليله، وأمينه على وحيه، نبينا وإمامنا محمد بن عبدالله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا شك أن العمرة عن الغير من الموتى أو العاجزين عن الوصول إلى مكة لكبر السن جائزة، كالحج، فلك -أيها السائل- أن تعتمر عمن شئت من إخوانك المسلمين الموتى، وإذا أحرمت تحرم عن الميت، كما تحرم عن نفسك، وتنوي العمرة عن الشخص الذي أردت أداءها عنه، والأفضل أن تقول: اللهم لبيك عمرة عن فلان، هذا هو الأفضل، وإن لم تقل: عن فلان، ونويتها عنه؛ كفى ذلك، ولا حاجة إلى اللفظ، وقد كان -عليه الصلاة والسلام- يصرح في تلبيته بالنسك، فثبت عنه -عليه الصلاة والسلام- أنه في حجة الوداع قال: اللهم لبيك عمرةً وحجًا. فالإخبار عن النسك الذي يريده الإنسان في تلبيته أمر مشروع، وإذا كان يريد ذلك عن غيره، فإنه يسمي، هذا هو الأفضل؛ ولهذا جاء في حديث ابن عباس أنه سمع رجلًا يقول: لبيك عن شبرمة، فقال: من شبرمة؟ قال: أخ لي، أو قريب لي، قال: حججت عن نفسك؟ قال: لا، قال: حج عن نفسك، ثم حج عن شبرمة فدل ذلك على أن الأفضل أنه يسمي من يحج عنه في تلبيته، نعم.","link":"https://binbaz.org.sa/fatwas/13579/مشروعية-العمرة-عن-الميت-والعاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65501.mp3","categories":["النيابة في الحج"]},{"id":15293,"question":"هل يجوز للإنسان أن يعتمر عن بعض إخوانه في الله، في عمرة واحدة، وماذا يقول إذا أراد أن يعتمر؟","title":"شروط العمرة عن الغير","answer":"الجواب: نعم، يجوز أن يعتمر عن أخيه في الله إذا كان ميتًا أو عاجزًا لهرم أو مرض لا يرجى برؤه، يعتمر له أو يحج عنه، مشكور ومأجور، إذا كان بهذا الشرط: إما ميت أو عاجز لهرم، أو كبر سن، أو لهرم أو مرض لا يرجى برؤه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13784/شروط-العمرة-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56521.mp3","categories":["النيابة في الحج"]},{"id":15796,"question":"بعد هذا ننتقل إلى سؤال آخر لأخينا صاحب هذه الرسالة؛ إذ يقول: حججت في العام الماضي، ولله الحمد والمنة، وقد رميت الجمرات عن زوجتي، ولم تكن حاملًا ولا مريضة، وكان معي أربعة أطفال صغار، وشاهدت الزحام فلم أرها تستطع الرمي، فهل هذا يجوز أم أنها تركت واجبًا؟ وماذا عليها الآن؟","title":"حكم التوكيل في رمي الجمرات","answer":"الجواب: إذا كان الحال ما ذكرتم فلا شيء عليها؛ لأن تعاطيها الرجم -رمي الحجارة- مع الأطفال خطر عظيم، ولرعاة الأطفال خطر عظيم، فهي معذورة بوجود الأطفال لديها بالتوكيل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14386/حكم-التوكيل-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74302.mp3","categories":["قضايا المرأة","رمي الجمار","النيابة في الحج"]},{"id":16258,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع: خالد شكر محمود، الأخ خالد عرضنا له سؤالًا في حلقة مضت، وفيه وصف نفسه بأنه عاجز بنسبة (100%) وأجبتم -جزاكم الله خيرًا- عن سؤاله عن الصلاة، وفي هذه الحلقة يسأل عن الحج، يقول: هل يجوز أن يحج عني بالنيابة؟ جزاكم الله خيرًا.","title":"هل يجوز لمن لديه شلل استنابة مَنْ يحج عنه؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فأنت أعلم بنفسك، إذا كنت تستطيع الحج؛ فعليك الحج، لقول الله -جل وعلا-: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] أما إذا كان الشلل الذي معك يمنعك من القدرة؛ لأنك لا تستطيع المشي، أو لا تستطيع الركوب. المقصود إذا كنت لا تستطيع الذهاب إلى مكة لهذا الشلل الذي أصابك، فأنت حكمك حكم المريض الذي لا يرجى برؤه، وحكم الشيخ الكبير العاجز عن السفر، تستنيب من ينوب عنك إذا كنت تقدر على المال، تستنيب من يحج عنك، والحمد لله. أما إن كنت تستطيع أن تذهب بنفسك؛ فعليك أن تحج بنفسك كسائر المسلمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14946/هل-يجوز-لمن-لديه-شلل-استنابة-من-يحج-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80801.mp3","categories":["النيابة في الحج"]},{"id":16338,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع أبو محمد بن أحمد علي، أخونا عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل سماحتكم شيخ عبدالعزيز فيقول: أنا شخص قد أديت الحج والعمرة -والحمد لله- وعندي نية أن أحج وأعتمر لوالدي، فهل أبدأ بالوالد، أم الوالدة؟ وهل يكون الحج للوالد، أم للوالدة؟ وكذلك العمرة؟ جزاكم الله خيرًا.","title":"تقدم الأم على الأب في الحج وغيره","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد دلت الأدلة الشرعية على أن الأم حقها أعظم وأكبر من حق الوالد الأب، ومن ذلك قوله -عليه الصلاة- ولما سأله سائل: قال: يا رسول الله! من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب.  وفي الصحيحين عنه ﷺ أنه قال لما سئل: أي الناس أحق بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك.  فإذا كان الوالدان لم يحجا، وقد ماتا قبل أن يحجا؛ تبدأ بالأم، ثم تحج عن الأب، وهكذا إذا كانا قد حجا جميعًا تبدأ بالأم، أما إذا كان الأم قد حجت، وهو لم يحج؛ تبدأ بالأب، تؤدي الحج عنه؛ لأنه ما حج، وهي قد حجت، والحمد لله. والحج عنهما قربة وطاعة، والصدقة عنهما، والدعاء لهما، والاستغفار لهما كله طاعة وقربة، حق عليك، ومشروع لك أن تدعو لهما، وأن تستغفر لهما، وأن تتصدق عنهما، هذا من البر بعد وفاتهما، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15032/تقدم-الام-على-الاب-في-الحج-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71401.mp3","categories":["النيابة في الحج"]},{"id":16531,"question":"سماحة الشيخ، هذه السائلة أم محمد أختكم في الله تقول: سماحة الشيخ هل يجوز أن ينوي الإنسان بالحج والعمرة، أن ينوي في نفس الوقت للحج له، وللعمرة، ينويها لوالدته، نظرًا لأن الوالدة ضعيفة السمع والبصر، ولا تستطيع أن تؤدي العمرة؟","title":"حكم الجمع بين الحج عن النفس والعمرة عن الغير","answer":"الجواب: نعم، لا حرج إذا أراد الإنسان أن يحج عن نفسه، ويعتمر عن أمه أو أبيه، أو العكس، يعتمر عن نفسه، ويحج عن أمه وأبيه لا بأس، إذا كانت أمه ميتة، أو أبوه ميتًا، أو عاجزين لكبر السن، أو لمرض لا يرجى برؤه، وقد حج عن نفسه، وقد اعتمر عن نفسه مأجور، هذا من البر والصلة، من البر أن يحج عن أبيه الميت، أو العاجز، ومن البر أن يحج عن أمه العاجزة، أو الميتة، أو يعتمر عنهما، كل هذا من البر، إذا كانا ميتين، أو عاجزين لكبر السن، أو لمرض لا يرجى برؤه، كل هذا رخص فيه النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/15251/حكم-الجمع-بين-الحج-عن-النفس-والعمرة-عن-الغير","audio":"","categories":["النيابة في الحج"]},{"id":16532,"question":"سماحة الشيخ! تقول السائلة أم أحمد: هل يجوز للزوجة أن توكل زوجها لرمي جمرة العقبة؟ وهل عليها هدي في ذلك، نظرًا للزحام، ومعها أطفال في ذلك الوقت؟","title":"هل يجوز للمرأة أن توكل زوجها لرمي الجمار؟","answer":"الجواب: نعم، إذا كانت عاجزة لها أن توكل زوجها، أو غيره، توكل ثقة يرمي عنها إذا كانت ضعيفة لا تستطيع الزحام، أو كبيرة السن لا تسطيع، أو عندها أطفال ما تستطيع تتركهم، توكل زوجها إذا كان ثقة، أو غيره من الثقات يرمي عنها، ولا حرج.","link":"https://binbaz.org.sa/fatwas/15253/هل-يجوز-للمراة-ان-توكل-زوجها-لرمي-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58308.mp3","categories":["رمي الجمار","النيابة في الحج"]},{"id":16642,"question":"من دولة قطر المستمع عبدالله إبراهيم عبدالله الهبندوي، أخونا له أسئلة من بينها سؤال يقول: والدي توفي، ولم يحج، وأنا لم أحج أيضًا، فهل لي أن أحج عنه، أم أبدأ بنفسي، جزاكم الله خيرًا؟","title":"لابد من الحج عن النفس قبل الحج عن الغير","answer":"الجواب: تبدأ بنفسك، تحج عن نفسك أولًا، ثم تحج عن أبيك، وأنت على خير، وأنت مأجور، جزاك الله خيرًا، لكن تبدأ بنفسك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15375/لابد-من-الحج-عن-النفس-قبل-الحج-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71705.mp3","categories":["النيابة في الحج"]},{"id":16684,"question":"من أسئلة هذه السائلة تقول: والدي على قيد الحياة، وأرغب في عمل عمرة له، حيث إنه غير قادر على أداء المناسك العمرة، فهل هناك رياء في إعلامه بأنني عملت له عمرة؟","title":"حكم العمرة عن الغير وإخباره بذلك","answer":"الجواب: إذا كان عاجزًا لكبر سنه، أو مرض لا يرجى برؤه، وحججت عنه؛ فلا بأس، ولو ما أعلمتيه، جزاك الله خيرًا، هذا من بره، إذا كان عاجزًا لكبر سنه، أو لأن المريض لا يرجى برؤه، وحججت عنه؛ فلا حاجة إلى إخباره، ولا سؤاله، وأبشري بالخير والأجر.","link":"https://binbaz.org.sa/fatwas/15431/حكم-العمرة-عن-الغير-واخباره-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58416.mp3","categories":["النيابة في الحج"]},{"id":16939,"question":"جزاكم الله خيرًا سماحة الشيخ، يقول السائل في ثاني أسئلته: والدي متوفى منذ أربع سنوات، ولكنه لم يحج، ولم يوص بالحج عنه؛ وذلك لأنه مات موتًا مفاجئًا، فما واجبنا، هل نحج عنه؟ علمًا بأنه لم يوصينا بذلك، وهل يجوز أن نقرأ له القرآن، وندفع مالًا على ذلك؟","title":"حكم الحج عن الميت وقراءة القرآن له","answer":"الجواب: إذا كان لم يحج، وخلف تركة؛ وجب أن يحج عنه من التركة إذا كان يستطيع الحج في حياته، ولكن تساهل وجب أن يخرج من ماله ما يحج به عنه، وإن حج عنه بعض أولاده كفى، أما إذا كان فقيرًا، مات ما يستطيع الحج، فإن أولاده إذا حجوا عنه مأجورون، لهم أجر إذا حج عنه بعض أولاده، أو إن حجت عنه زوجته، أو بعض أقاربه مأجورون، أما إذا كان لا، يستطيع الحج، عنده قدرة ولكن تساهل؛ فإنه يجب أن يخرج من ماله حجة، يعطاها الثقة حتى يحج بها عنه، وإن حج عنه بعض أولاده الطيبين كفى. المقدم: وبالنسبة لقراءة القرآن يقول يا سماحة الشيخ؟ الجواب: أما أن يقرأ على الميت، يقرأ القرآن على الميت هذا لا دليل عليه، ولا يشرع، ولكن يدعى له، أما قراءة القرآن للموتى هذا لا دليل عليه، ولا يشرع، لكن السنة أن يدعى للميت، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، يعتمر عنه، كل هذا طيب.  أما أن يقرأ قرآنًا يثوبه له، هذا لا دليل عليه، أو يقرأ عند قبره هذا كله منكر، لكن إذا قرأ له في البيت، أو في المسجد ينويه له هذا لا دليل عليه، تركه أولى، ولكن يدعو له، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، أو يعتمر عنه، نعم.","link":"https://binbaz.org.sa/fatwas/15713/حكم-الحج-عن-الميت-وقراءة-القران-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58612.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":17068,"question":"يقول السائل: هل يلزم أهل الميت العيد له -أي: ذبح الأضحية- في عيد الأضحى له؟","title":"حكم التضحية عن الميت","answer":"الجواب: لا يلزمهم، لكن إذا ضحوا فهم مأجورون، من باب التطوع، كالصدقة عنه، وإلا فلا يلزمهم، إلا إذا أوصى بذلك، أوصى في بيت، أو مزرعة عليهم أن ينفذوا الوصية في الثلث فأقل. أما إذا كان ما أوصى فلا يلزمهم، لكن إذا تطوعوا ضحوا عنه، أو تصدقوا عنه فلهم أجر، لقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقةٍ جارية، أو علمٍ ينتفع به، أو ولدٍ صالح يدعو له «وسأله رجل قال: يا رسول الله! إن أمي ماتت، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. هذا يدل على أنه إذا تصدق عن أمه، أو أبيه، أو فلان، أو فلان له أجر. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15873/حكم-التضحية-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58808.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":17141,"question":"تقول أختنا: توفيت أمي وأنا صغيرة مع أعمامي، وقد كانت بعيدة عني، أعطت أحد أقاربي أمانة أن يحج عنها؛ لأن أبي كان متوفيًا أيضًا، لكني سمعت من بعض الأشخاص أنه لا يجوز الحج عن الأم قبل الأب، فما مدى صحة ذلك؟","title":"ما حكم الحج عن الأم قبل الأب؟","answer":"الجواب: هذا غلط، لا بأس، هذا غلط، الذي سمعتِ أنه لا يحج عن الأم قبل الأب هذا غلط، بل يحج عن الأم قبل الأب، والأب قبل الأم ولا حرج في ذلك، والأم أحق بالبر، حقها أعظم من حق الأب، فإذا حج الإنسان عن أمه قبل أبيه؛ فلا حرج عليه، بل قد أصاب السنة، وأصاب الفضل؛ فإن حقها أعظم، سئل النبي ﷺ.. قال له رجل: يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. وفي الحديث الآخر يقول ﷺ لما سأله سائل: يا رسول الله! من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب فالأب في الرابعة. فإذا كانا ما حجا جميعًا يبدأ بالأم أفضل، ثم يحج عن الأب إذا كانا ماتا ولم يحجا. أما إن كان أحدهما قد حج يحج عن الذي لم يحج، وإن حج عنهما مرات كثيرة هذا من البر، وجزاه الله خيرًا، سواء كان الحاج ابنهما، أو بنتهما، أو أخاهما، أو أختهما، الأمر واسع والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16020/ما-حكم-الحج-عن-الام-قبل-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83208.mp3","categories":["النيابة في الحج"]},{"id":17458,"question":"هذه سائلة تقول: بأنها تعمل في المملكة، ومقيمة هنا في المملكة، وقد أدت فريضة الحج، وتحمد الله على ذلك، تقول: والدتي كبيرة في السن، تبلغ أكثر من الستين، وقد صعب عليها الأمر في أداء فريضة الحج، ولا تملك القدرة الكافية لمصاريف الحج، وهناك عقبات أخرى تقول: أريد الحج عنها حيث أنني هنا أعمل في المملكة، فهل يجوز لي أن أؤدي عنها فريضة الحج؟","title":"ما حكم الحج عن الكبير الذي لا يملك نفقة الحج؟","answer":"الجواب: إذا كانت لا تستطيع لكبر سنها، وعجزها؛ فلا بأس، أما لقلة المال لا، النبي ﷺ جاءته امرأة، فقالت: يا رسول الله! إن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عن أبيك وجاءه رجل، فقال: إن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه وأعتمر؟ قال: حج عن أبيك، واعتمر. أما إن كانت تستطيع أن تذهب، وأن تطوف، وتسعى، ولكن ما عندها مال لا تحجي عنها، وإذا قدرت فتحج، وإن لم تقدر فهي معذورة والحمد لله؛ لأن الله يقول سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] فالحج إنما يجب مع الاستطاعة، فإذا كانت عاجزة ما عندها مال؛ فلا حج عليها، وإذا عجزت من جهة السن، ولم تستطع من جهة السن لضعف بدنها، وقلة قوتها، وعجزها تحجين عنها، أو ماتت كذلك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16327/ما-حكم-الحج-عن-الكبير-الذي-لا-يملك-نفقة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77215.mp3","categories":["النيابة في الحج"]},{"id":17466,"question":"من دولة الكويت الأخت المستمعة (د. م. ن) سألت ثلاثة أسئلة، في سؤالها الأول تقول سماحة الشيخ: كان لي أخوان أحدهما في سن الثالثة عشرة، والآخر في سن الخامسة عشرة، وقعا في حفرة، وماتا مختنقين تحت التراب، سؤالي: هل عليهما تكليف، فنستغفر الله لهما، ونحج عنهما، ونعتمر عنهما؟ وهل يعتبران من الشهداء؟ جزاكم الله خيرًا.","title":"هل يعتبر من الشهداء من سقط في حفرة فمات؟","answer":"الجواب: يرجى لهما خير، وإذا كانا لم يبلغا الحلم؛ فإنهما لا شيء عليهما من جهة التكليف، أي: من جهة الإثم، ولهما أجر أعمالهما الطيبة من صلاة وذكر وقراءة ونحو ذلك، هذان أحدهما قد بلغ الخامسة عشرة، فإذا كان قد كمّلها هو مُكَلَّف، وإذا كان لم يكملها، ولم يعرف أنه أنبت الشعر حول الشعرة، ولا يعرف أنه أنزل المني للشهوة، فهو غير مكلف، ولكن إذا حج عنه، أو اعتمر عنه، أو تصدق عنه وعن أخيه كله ينفع، كله نافع، وخير، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، و أحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16334/هل-يعتبر-من-الشهداء-من-سقط-في-حفرة-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72503.mp3","categories":["النيابة في الحج"]},{"id":18089,"question":"يقول: هل يجوز للرجل أن يقول لابنه: حج عني، مع أنه على خير حال؟ وله من المال ما يمكنه من الحج؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الحج عن القادر على الحج","answer":"الجواب: لا، لا يجوز له أن يحج عن أبيه، ولا عن غير أبيه، مادام أبوه يستطيع الحج، ولا يقول له: حج عني، لا يقول له أبوه: حج عني، لأن هذا لا يجوز، إنما الحج عن الميت، أو العاجز، كبير السن، العجوز الكبيرة، أو الرجل الكبير، أو المريض الذي لا يرجى برؤه، هذا يحج عنه، لا بأس. أما إنسانٌ صحيح، أو مريض مرض عاجز، يرجى برؤه، هذا لا يحج عنه، لا بأمره، ولا بغير أمره، لا عن أب، ولا عن غيره. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17124/حكم-الحج-عن-القادر-على-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73013.mp3","categories":["النيابة في الحج"]},{"id":18120,"question":"هذا السائل (عبد الكريم . أ. أ) يقول: سماحة الشيخ! ما حكم الأضحية عن الميت؛ حيث إن البعض من الناس يقولون: بأن الأضحية عن الميت بدعة، فهي للأحياء وجهونا في ذلك؟","title":"هل الأضحية عن الميت بدعة؟","answer":"الجواب: الأضحية سنة عن الحي والميت، والذي يقول: إنها بدعة، قد غلط، والصواب أنها سنة عن الحي والميت، وقد ضحى النبي ﷺ بكبشين أحدهما عن محمد وآله وفيهم الميت كبناته، وضحى بكبش ثان عن من وحد الله من أمة محمد، وفيهم الحي والميت، فالضحية عن الميت قربة وطاعة كالحي، فإذا ضحى عن أبيه الميت، أو عن أمه الميتة، أو عن أخيه، أو زوجته؛ فكله قربة وكله طاعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17162/هل-الاضحية-عن-الميت-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78109.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":18126,"question":"من لواء صعدة - الجمهورية العربية اليمنية أخونا عوض جابر ضافر هدلق، يسأل مجموعة من الأسئلة من بينها سؤال عن شخص يريد أن يحج عن والدته وهي حية؟","title":"حكم الحج عن الحي","answer":"الجواب: هذا ينظر في شأنها فإن كانت عاجزة لكبر السن، أو لمرض لا يرجى برؤه؛ فإنه يحج عنها وهو مأجور؛ لما ثبت في الصحيحين: أن امرأة من خثعم قالت: يا رسول الله! إن أبي أدركته فريضة الله في الحج، وهو شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال النبي: حجي عنه عليه الصلاة والسلام، وهكذا سأله رجل قال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الضعن أفأحج عنه، قال: حج عن أبيك واعتمر. فإذا كان الأب أو الأم عاجزين ضعيفين لكبر سنهما، أو لمرض أصابهما لا يرجى برؤه شرع أن يحج عنهما ولدهما أو غيره من أقاربهما، وهكذا إذا كان الأب ميتًا أو الأم ميتة يحج عنهما. نعم.","link":"https://binbaz.org.sa/fatwas/17184/حكم-الحج-عن-الحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85207.mp3","categories":["النيابة في الحج"]},{"id":18251,"question":"أم عبد العزيز يا سماحة الشيخ! في سؤالها هذا كتبته بأسلوبها الخاص تقول: بأنها اعتمرت لوالدها المتوفى، في نهاية العمرة نسيت أن تقصر من شعرها، هذه الفقرة الأولى يا شيخ؟","title":"حكم من اعتمرت عن والدها المتوفى فنسيت التقصير","answer":"الجواب: الحج عن الميت والعمرة عن الميت لا بأس به، لا بأس أن تحج عن الميت وأن تعتمر عن الميت، لا حرج في ذلك والحمد لله، وهكذا الشيخ الهرم والعجوز الهرمة العاجزين، لا بأس أن يحج عنهما أو يعتمر عنهما أبناؤهما أو غيرهم؛ لأنهما كالميت. وأما الحي القادر فلا يعتمر عنه، ولا يطاف عنه، الطواف عن الحي القادر لا، لا يطاف عن الحي، إنما يحج عنه أو يعتمر، والميت كذلك إنما يحج عنه ويعتمر، أما الطواف كالصلاة لا يصلى عن زيد ولا يطاف عن زيد، ما نعلم دليلًا على هذا الشيء، لكن تطوف لنفسه، الإنسان يطوف لنفسه، والمرأة تطوف لنفسها، أما أنها تطوف عن أمها، أو أبيها، أو تصلي عنهما هذا لا دليل عليه ولا يشرع. وأما إذا نسيت التقصير تقصر متى ذكرت الحمد لله، ولو في بلدها، ولو في الطريق. المقدم: ولو فصل وقت طويل يا شيخ؟ الشيخ: ولو، متى ذكرت تقصر بنية العمرة. المقدم: جزاكم الله عنا، وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17300/حكم-من-اعتمرت-عن-والدها-المتوفى-فنسيت-التقصير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78307.mp3","categories":["النيابة في الحج"]},{"id":18386,"question":"السائلة في آخر أسئلتها تقول: اعتمرت عمرة، ولكنني أريد أن أعمل عمرة لوالدي المتوفى، ما هي الأمور التي يجب علي في مثل هذا العمل، وكيف أنوي لوالدي عند الإحرام؟","title":"كيفية الحج والعمرة عن المتوفى","answer":"الجواب: المعتمر عن غيره كالمعتمر عن نفسه، والحاج عن غيره كالحاج عن نفسه، يفعل ما يفعل لو حج عن نفسه، أو اعتمر لنفسه، يحرم من الميقات إذا كان خارج المواقيت، إذا مر بالميقات ينوي الحج عن أبيه أو عن غيره من الأموات، أو العاجزين لكبر السن أو مرض لا يرجى برؤه ينوي بقلبه، ويقول: لبيك حجًا عن فلان، أو لبيك عمرة عن فلان، ثم يلبي التلبية الشرعية: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك. ويستمر في التلبية، ثم يؤدي الطواف بالنية عن صاحبه، والسعي عن صاحبه وهكذا في الحج كرمي الجمار وبعرفة وغير ذلك، ينوي الأعمال كلها عن صاحبه، بالنية بقلبه، والحمد لله، سواء كان حج عن أبيه أو عن أخيه أو عن غيره من الأموات أو عن أبيه العاجز الشيخ الكبير الهرم أو الأم العاجزة أو غيرهما ممن لا يستطيع الحج والعمرة لكبر سن أو مرض لا يرجى برؤه، بالنية بنية القلب، إلا أنه يستحب له عند الإحرام أن يقول: لبيك عن فلان، لبيك حجًا عن فلان، أو لبيك عمرة عن فلان، والبقية النية كافية فيه، نية القلب تكفي. نعم.","link":"https://binbaz.org.sa/fatwas/17456/كيفية-الحج-والعمرة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78406.mp3","categories":["النيابة في الحج"]},{"id":18467,"question":"هل لي أن أحج عن ولدي المعوق إعاقة سمعية وكلامية منذ الصغر؟","title":"حكم الحج عن المعوق إعاقة سمعية وكلامية","answer":"الجواب: إذا بلغ الحلم، كلف واستطاع الحج يحج بنفسه، ولا يمنع الحج كونه لا يسمع أو لا يتكلم؛ فإن هذا لا يمنع الحج، في إمكانه أن يحج مع الناس ويحضر المشاعر، وإن كان لا يتكلم وإن كان لا يسمع. أما إذا عجز بعد كبر السن هذا يحج عنه أو مات، أما كونه قويًا يستطيع الحج، ولكنه ليس بسميع أو ليس بمتكلم هذا لا يمنع، كما أنه لا يمنع العمى؛ فالأعمى والأصم والأبكم كل هؤلاء عليهم الحج إذا استطاعوا، ويحضرون مع الناس، ويحضرون عرفات والمشاعر، ويفعلون ما شرع الله جل وعلا ويسقط عنهم الكلام من التلبية ونحوها؛ لأنهم معذورون. نعم.","link":"https://binbaz.org.sa/fatwas/17575/حكم-الحج-عن-المعوق-اعاقة-سمعية-وكلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86611.mp3","categories":["النيابة في الحج"]},{"id":18476,"question":"هل لي أن أحج عن ولدي المعوق إعاقة سمعية وكلامية منذ الصغر؟","title":"حكم الحج عن المعوق إعاقة سمعية وكلامية","answer":"الجواب: إذا بلغ الحلم، كلف واستطاع الحج يحج بنفسه، ولا يمنع الحج كونه لا يسمع أو لا يتكلم؛ فإن هذا لا يمنع الحج، في إمكانه أن يحج مع الناس ويحضر المشاعر، وإن كان لا يتكلم وإن كان لا يسمع. أما إذا عجز بعد كبر السن هذا يحج عنه أو مات، أما كونه قويًا يستطيع الحج، ولكنه ليس بسميع أو ليس بمتكلم هذا لا يمنع، كما أنه لا يمنع العمى؛ فالأعمى والأصم والأبكم كل هؤلاء عليهم الحج إذا استطاعوا، ويحضرون مع الناس، ويحضرون عرفات والمشاعر، ويفعلون ما شرع الله جل وعلا ويسقط عنهم الكلام من التلبية ونحوها؛ لأنهم معذورون. نعم.","link":"https://binbaz.org.sa/fatwas/17575/حكم-الحج-عن-المعوق-اعاقة-سمعية-وكلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86611.mp3","categories":["النيابة في الحج"]},{"id":18687,"question":"سماحة الشيخ، في سؤاله الثاني يقول: بأن زوجته المقيمة بمصر لم تحج؛ لأنها لم تستطع ماليًا، وهناك صعوبات مالية، ويترتب على ذلك مشقة عليها، هل يجوز لهذا الزوج أن يقوم بالحج عنها؟","title":"حكم الحج عن شخص حي لعدم الاستطاعة","answer":"الجواب: عليها أن تحج إذا استطاعت، وإذا لم تستطع فلا حج عليها؛ لقول الله -جل وعلا-: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97] فإذا كانت تستطيع بدنها ومالها حجت، وإن كانت لا تستطيع لا يلزمها الحج حتى يوجد عندها مال، أو يتيسر لزوجها تحجيجها، أو غيره ممن يحججها لا بأس. المقصود: لا يلزمها إلا إذا استطاعت الحج من مالها، أما إذا كانت هرمة عجوز كبيرة يشق عليها الحج يحج عنها زوجها أو غيره، أما إذا كانت تستطيع ببدنها، ولكن ما عندها مال فليس عليها حج حتى تستطيع المال، فإذا وجد المال تحج، وإن حججها زوجها أو أبوها أو غيرهما فلا بأس، لكن لا يلزمها الحج إلا إذا استطاعت بمالها هي وبدنها، إذا استطاعت لزمها الحج، وإلا فلا، ولا حرج عليها؛ لأن الله يقول: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97].  ولا يجزي عنها الحج إذا حج عنها غيرها وهي تستطيع ببدنها وليست بهرمة، ولا بعجوز كبيرة، ولا مريضة مرضًا لا يرجى برؤه، لا يحج عنها، أما إذا كانت هرمة عجوز، أو مريضة مرض لا يرجى برؤه؛ فلا بأس أن يحج عنها زوجها أو غيره، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17810/حكم-الحج-عن-شخص-حي-لعدم-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78810.mp3","categories":["النيابة في الحج"]},{"id":18702,"question":"بعد هذا سماحة الشيخ ننتقل إلى رسالة بعث بها المستمع طارق محمد الغران في مكة المكرمة، أخونا يسأل ويقول: ما حكم الحج عن الجد المتوفى أبو الوالدة من مالي الخاص؟ وليس هناك له مال، وجهوني جزاكم الله خيرًا؛ إذ أنه لم يحج عن نفسه.","title":"حكم الحج عن الميت الذي لم يحج","answer":"الجواب: أنت مشكور، جزاك الله خيرًا، الحج عنه طيب، جزاك الله خيرًا، هذا من البر والصلة إذا حججت عنه، فأنت مشكور جزاك الله خيرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17806/حكم-الحج-عن-الميت-الذي-لم-يحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73514.mp3","categories":["النيابة في الحج"]},{"id":18809,"question":"هل يجوز الحج قبل الوالدين؟ وإذا كان أحد الوالدين مصاب بمرض عقلي هل يجوز الحج عنه؟أفيدونا أثابكم الله.","title":"حكم حج الولد قبل والديه والحج عن فاقد العقل منهما","answer":"الجواب: لا حرج أن يحج الإنسان قبل والده، لا بأس أن يحج قبل أمه، وقبل أبيه؛ لأنه قد يتيسر له الحج ولا يتيسر لهما، فلا حرج في ذلك، ولا نعلم خلافًا في هذا بين أهل العلم. وإذا كان الوالد مجنونًا، أو فاقد العقل من غير جنون؛ فلا بأس أن يحج عنه، أن يحج عنه ولده برًا له، سواء كان الوالد أبًا أو أمًا؛ لأن الحج الذي لا يصح من المجنون إذا باشره بنفسه، ما يصح حج المجنون والمعتوه إذا باشره بنفسه، أما إذا كان حج عنه غيره فلا بأس بذلك، وليس عليه حج فريضة، إذا بلغ وهو مجنون لا حج عليه، لكن لو حج عنه ولده، أو أخوه أو غيرهما؛ فلا بأس، وله أجر ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17934/حكم-حج-الولد-قبل-والديه-والحج-عن-فاقد-العقل-منهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87609.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":18920,"question":"هذا سائل يقول: أرجو إفادتي في هذا  فقد حجيت عن نفسي في السنة الماضية، ولي نية أن أحج عن جدتي المتوفاة، هل هو هذا جائز؟","title":"حكم الحج عن الجدة لمن كان قد حج عن نفسه","answer":"الجواب: لك أجر إذا حججت عن جدتك المتوفاة، أو أمك أو خالتك أو أختك أو أبيك أو عمك، أنت مأجور ومحسن، نعم.","link":"https://binbaz.org.sa/fatwas/18085/حكم-الحج-عن-الجدة-لمن-كان-قد-حج-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88215.mp3","categories":["النيابة في الحج"]},{"id":18998,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الأخ المستمع: محمد صبحي محمود كرم، مدرس مصري، أخونا عرضنا جزءًا كبيرًا من أسئلته في حلقة مضت، وكانت عن حكم رفع القبور للاضطرار، ولاسيما إذا كانت الأرض صلبة لا تنحفر، أو كانت تنحفر ولكنها تنهار على الموتى.تفضلتم سماحة الشيخ وبينتم وأجبتم إجابة شافية كافية في حلقة سبقت، وهذه الحلقة يعرض أخونا جزءًا من أسئلة أخرى فيقول في أحدها: هل يجوز أن أحج عن أمي التي ما زالت على قيد الحياة، نظرًا لعدم استطاعتها المادية؟ لكنها يمكنها أداء المناسك، مع العلم بأنني حججت عن نفسي والحمد لله، نسأل الله القبول؟","title":"حكم الحج والعمرة عن القادر على أداء المناسك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: أيها الأخ السائل: ليس لك أن تحج عنها؛ ما دامت تستطيع الحج لنفسها، ولكن تبذل وسعك في أن تحججها من مالك إذا تيسر لك ذلك. أما الحج عنها فلا؛ لأن الحج عن الحي لا بد أن يكون لعجزه بسبب كبر السن، أو مرض لا يرجى برؤه، كما جاءت بذلك الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام. أما الشيخ الكبير والعجوز الكبيرة إذا كانا قادرين فلا يحج عنهما، كما لا يحج عن الشباب، بل إن استطاع الحج فالحمد لله، وإلا فهو معذور، يقول الله سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97]، فمن استطاع الزاد والراحلة، استطاع أجرة السيارة، تذكرة الطائرة، والمئونة؛ حج وإلا فلا حرج عليه والحمد لله. وليس عليك أنت أن تحج عنها، بل إن قدرت أن تحججها من مالك فجزاك الله خيرًا، وهذا من برها، وإلا فلا يلزمها الحج إلا إذا استطاعت بمالها هي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18155/حكم-الحج-والعمرة-عن-القادر-على-اداء-المناسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_794/nour_79401.mp3","categories":["النيابة في الحج"]},{"id":19354,"question":"أبي كان قد نوى فريضة الحج، وفي منتصف الطريق توفي بحادث اصطدام سيارة، فهل يعتبر حاجًا؟ أم يلزمنا أن نحج من أجله؟","title":"حكم أداء الحج عمن توفي وهو في طريقه للحج","answer":"الجواب: إن كان مات قبل الإحرام فالحج باق؛ إذا كان يستطيع الحج ورث تركة فعليكم أن تحججوا عنه من تركته، إذا كان غنيًا يستطيع الحج في حياته فعليكم أن تحججوا عنه، وإن حج بعضكم تبرعًا عن والدكم فجزاكم الله خيرًا. أما إن كان موته بعد إحرامه بالحج، فهذا لا شيء عليه؛ لأن الرسول ﷺ لما مات بعض الصحابة في عرفات قال: إنه يبعث يوم القيامة ملبيًا ولم يأمر بالحج عنه بل قال: اغسلوه بماء وسدر وكفنوه في ثوبيه ولا تحنطوه -يعني: لا تطيبوه- ولا تخمروا رأسه ووجهه؛ فإنه يبعث يوم القيامة ملبيًا فدل ذلك على أنه باق على إحرامه وأنه لا يكلف أحد بالحج عنه، والذي مات بعد الإحرام مثل الذي مات في عرفات سواء، لا يجب أن يحج عنه، فمن حج عنه من باب التبرع ومن باب الخير فلا بأس. المقدم: بارك الله فيكم، إذا كان حصل الحادث قبل أن يدخل الإحرام سماحة الشيخ؟ الشيخ: هذا مثلما تقدم يحج عنه، إن كان غنيًا يحجج من ماله، وإن كان فقيرًا فلا حج عليه، لكن إذا حج عنه بعض أقاربه أو بعض أولاده فهذا حسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18567/حكم-اداء-الحج-عمن-توفي-وهو-في-طريقه-للحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90004.mp3","categories":["النيابة في الحج"]},{"id":19422,"question":"يقول: لي صديق مؤمن في مصر هل يجوز لي أن أؤدي عنه عمرة بشرط أن يقرأ هو القرآن عدة مرات ويهب ثواب ذلك لوالدي؟","title":"حكم من اعتمر عن غيره بشرط","answer":"الجواب: إذا كان عاجزًا: كالشيخ الكبير، والعجوز الكبيرة، والمريض الذي لا يرجى برؤه؛ جاز لك أن تحج عنه؛ وأنت مأجور، لكن بدون هذا الشرط، بدون شرط أن يقرأ لك، بل تبرعًا منك، أو بمال يعطيك إياه تحج عنه. أما القراءة فهذا لا أصل له، القراءة للغير ليس لها أصل شرعي يعتمد، ولكن إذا كافأك بمال، اتفقت عليه أنت وإياه على أنه يعطيك كذا وكذا وتحج عنه؛ لأنه مريض مرضًا لا يرجى برؤه، أو لأنه كبير في السن عاجز، أو أعطاك إياه تحج عن ميت؛ فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18653/حكم-من-اعتمر-عن-غيره-بشرط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74012.mp3","categories":["النيابة في الحج"]},{"id":19709,"question":"رجل حاج كبير السن لما أراد يرمي الجمار وكّل رجلاً ما أتى حاجًّا إنما أتى للعمل مع الدولة في الشرطة أو في غيرها؟","title":"هل يجوز توكيل شخص لم يأت حاجًّا في الرمي؟","answer":"لا، لا بد يكون حاجًّا، الوكيل لا بدّ يكون من الحجاج.","link":"https://binbaz.org.sa/fatwas/27024/هل-يجوز-توكيل-شخص-لم-يات-حاجا-في-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%87%D9%84%20%D9%8A%D8%AC%D9%88%D8%B2%20%D8%AA%D9%88%D9%83%D9%8A%D9%84%20%D8%B4%D8%AE%D8%B5%20%D9%84%D9%85%20%D9%8A%D8%A3%D8%AA%20%D8%AD%D8%A7%D8%AC%D9%91%D9%8B%D8%A7%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%B1%D9%85%D9%8A.mp3","categories":["رمي الجمار","النيابة في الحج"]}]
